 3	
 4	#include <string>
 5	#include <string_view>
 6	
 7	namespace tapa::cc {
 8	
 9	// The tapacc <-> tapa-rtl / tapa-ir textual ABI: the exact spellings the
10	// downstream tools expect in generated code and metadata. Changing any of these
11	// is a cross-tool break, so they live in one documented place.
12	
13	// The scalar base-address parameter an mmap lowers to: "<base>_offset".
14	inline std::string OffsetName(std::string_view base) {
15	  return std::string(base) + "_offset";
16	}
17	
18	// The i-th channel of an `mmaps` port as a flat offset parameter:
19	// "<base>_<i>_offset".
20	inline std::string ArrayElemOffset(std::string_view base, int i) {
21	  return std::string(base) + "_" + std::to_string(i) + "_offset";
22	}
23	
24	// The i-th element of an array interface as a C++ subscript: "<base>[<i>]".
25	inline std::string ArrayNameAt(std::string_view base, int i) {
26	  return std::string(base) + "[" + std::to_string(i) + "]";
27	}
28	
29	// The internal FIFO member of a stream: "<name>._".
30	inline std::string FifoVar(std::string_view name) {
31	  return std::string(name) + "._";
32	}
33	
34	// The peek FIFO member of an istream: "<name>._peek".
35	inline std::string PeekVar(std::string_view name) {
36	  return std::string(name) + "._peek";
37	}
38	
39	// Prefix for mangled task names, so an emitted symbol never starts with '_'
40	// (which Vitis rejects).
41	inline constexpr std::string_view kMangledPrefix = "tapa_mangled";
42	
43	}  // namespace tapa::cc
44	
45	#endif  // TAPA_CODEGEN_CONVENTIONS_H_

