     1	#ifndef TAPA_FRONTEND_PROGRAM_H_
     2	#define TAPA_FRONTEND_PROGRAM_H_
     3	
     4	#include <cstdint>
     5	#include <map>
     6	#include <optional>
     7	#include <string>
     8	#include <vector>
     9	
    10	#include "clang/AST/Decl.h"
    11	
    12	#include "classify.h"
    13	
    14	namespace tapa::cc {
    15	
    16	// Where a task is in the dataflow hierarchy.
    17	enum class TaskLevel { kUpper, kLower };
    18	
    19	// The synthesis target resolved for a task: the tool-wide `--target` unless a
    20	// `[[tapa::target(...)]]` attribute overrides it. Vendors are grouped, so
    21	// xilinx-hls and xilinx-vitis are distinct values handled by one backend.
    22	enum class SynthTarget { kXilinxHls, kXilinxVitis, kIgnore };
    23	
    24	// One external port of a task (an entry in the emitted task graph's "ports").
    25	struct Port {
    26	  std::string name;
    27	  TapaKind kind;      // serialized "cat" via TapaKindCat(kind)
    28	  std::string ctype;  // C++ type string, e.g. "const float*", "uint64_t"
    29	  uint32_t width = 0;
    30	  std::optional<uint32_t> chan_count;  // hmap / istreams / ostreams
    31	  std::optional<uint32_t> chan_size;   // hmap
    32	};
    33	
    34	// One argument of a child invocation: the resolved parent-scope name (a port /
    35	// FIFO name, or a Verilog literal like "64'd5") plus the category of the child
    36	// port it binds to.
    37	struct Arg {
    38	  std::string arg;
    39	  TapaKind cat;
    40	};
    41	
    42	// One instantiation of a child task within an upper task (post vec-expansion).
    43	struct Instance {
    44	  const clang::FunctionDecl* callee = nullptr;
    45	  std::string task_name;            // mangled name for template specializations
    46	  int64_t step = 0;                 // join=0, detach=-1, sequential>=1
    47	  std::optional<std::string> name;  // explicit invoke("name", ...)
    48	  std::map<std::string, Arg> args;  // child-port name -> binding
    49	};
    50	
    51	// A producer/consumer reference: the child instance that drives or drains a
    52	// FIFO, identified by task name and its index within that task's instance list
    53	// (serialized as the `[task, index]` endpoint pair).
    54	struct Endpoint {
    55	  std::string task;
    56	  uint32_t index = 0;
    57	};
    58	
    59	// A FIFO inside an upper task: either a declared `tapa::stream`/`tapa::streams`
    60	// (depth set, `decl` points at the VarDecl) or, at the top level only, a stream
    61	// port of the top task bound to a child (no depth, null `decl`) — an "external"
    62	// FIFO whose other endpoint is the kernel boundary.
    63	struct StreamDecl {
    64	  std::optional<uint64_t> depth;
    65	  const clang::VarDecl* decl = nullptr;
    66	  std::optional<Endpoint> produced_by;
    67	  std::optional<Endpoint> consumed_by;
    68	};
    69	
    70	// The typed model of one TAPA task. Built by the frontend with no source
    71	// rewriting; consumed by codegen and (later) the JSON serializer. Every field
    72	// is computed once here, so level/target/name are never recomputed downstream.
    73	struct TaskModel {
    74	  const clang::FunctionDecl* def = nullptr;  // the definition
    75	  // The function whose body instantiates this task; the mangled wrapper for a
    76	  // template specialization is emitted right after it. Null for non-specialized
    77	  // tasks.
    78	  const clang::FunctionDecl* invoker = nullptr;
    79	  bool is_template_spec = false;
    80	
    81	  std::string name;           // task key (mangled for template specializations)
    82	  std::string readable_name;  // pretty (templated) name; == name otherwise
    83	  TaskLevel level = TaskLevel::kLower;
    84	  SynthTarget target = SynthTarget::kXilinxHls;
    85	
    86	  std::vector<Port> ports;
    87	
    88	  // Upper tasks only: child instantiations keyed by child task name, and FIFOs
    89	  // keyed by variable name. Ordered maps -> deterministic output (§8.5), never
    90	  // pointer-keyed.
    91	  std::map<std::string, std::vector<Instance>> instances;
    92	  std::map<std::string, StreamDecl> streams;
    93	};
    94	
    95	// The whole program: the top-level task name, the ordered list of global
    96	// functions defined in the main file (drives codegen's per-task file assembly),
    97	// and every TAPA task reachable from the top, keyed by name.
    98	struct Program {
    99	  std::string top;
   100	  std::vector<const clang::FunctionDecl*> file_funcs;
   101	  std::map<std::string, TaskModel> tasks;
   102	};
   103	
   104	}  // namespace tapa::cc
   105	
   106	#endif  // TAPA_FRONTEND_PROGRAM_H_
