     1	//! Task definition types.
     2	
     3	use std::collections::BTreeMap;
     4	
     5	use indexmap::IndexMap;
     6	use serde::{Deserialize, Serialize};
     7	use serde_json::Value;
     8	
     9	use crate::instance::TaskInstance;
    10	use crate::interconnect::InterconnectDefinition;
    11	use crate::port::Port;
    12	use crate::synth_target::SynthTarget;
