     1	//! Root task-graph container.
     2	//!
     3	//! `TaskGraph` is the single root type for both the `tapacc` output and the
     4	//! post-synthesis design model; it is persisted inside the work dir's
     5	//! `tapa.json`, which `tapa pack` copies verbatim into the `.zip` archive for
     6	//! `frt-cosim` to read back.
     7	//! Field declaration order is stable so serializing re-emits keys
     8	//! deterministically; `tasks` uses [`BTreeMap`] so keys come out
     9	//! alphabetically, matching the sorted order `tapa analyze` writes.
    10	
    11	use std::collections::BTreeMap;
    12	use std::io::Read;
    13	
    14	use serde::{Deserialize, Serialize};
    15	
    16	use crate::error::ParseError;
    17	use crate::target::Target;
    18	use crate::task::Task;
    19	
    20	/// Root of the unified task graph.
    21	#[allow(
    22	    clippy::derive_partial_eq_without_eq,
    23	    reason = "transitively holds serde_json::Value through Task"
    24	)]
    25	#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
    26	#[serde(deny_unknown_fields)]
    27	pub struct TaskGraph {
    28	    /// Name of the top-level task.
    29	    pub top: String,
    30	    /// Compilation flow target, e.g. [`Target::XilinxVitis`]. Serializes as
    31	    /// the wire string `"xilinx-vitis"` / `"xilinx-hls"`.
    32	    pub target: Target,
    33	    /// C++ compiler flags.
    34	    #[serde(default)]
    35	    pub cflags: Vec<String>,
    36	    /// Task definitions keyed by task name.
    37	    pub tasks: BTreeMap<String, Task>,
    38	}
    39	
    40	impl TaskGraph {
    41	    /// Parse a task-graph payload with field-path error diagnostics.
    42	    pub fn from_json(json: &str) -> Result<Self, ParseError> {
    43	        let de = &mut serde_json::Deserializer::from_str(json);
    44	        serde_path_to_error::deserialize(de).map_err(|e| ParseError::Schema {
    45	            path: e.path().to_string(),
    46	            message: e.inner().to_string(),
    47	        })
    48	    }
    49	
    50	    /// Parse from any reader.
    51	    pub fn from_reader<R: Read>(mut reader: R) -> Result<Self, ParseError> {
    52	        let mut buf = String::new();
    53	        reader.read_to_string(&mut buf)?;
    54	        Self::from_json(&buf)
    55	    }
    56	}
    57	
    58	#[cfg(test)]
    59	mod tests {
    60	    use super::*;
    61	
    62	    #[test]
    63	    fn parses_named_child_instances() {
    64	        TaskGraph::from_json(
    65	            r#"{
    66	              "cflags": [],
    67	              "top": "Top",
    68	              "target": "xilinx-hls",
    69	              "tasks": {
    70	                "Leaf": {
    71	                    "readable_name": "Leaf",
    72	                  "code": "void Leaf() {}",
    73	                  "level": "lower",
    74	                  "synth": "hls",
    75	                  "ports": [],
    76	                  "tasks": {},
    77	                  "fifos": {}
    78	                },
    79	                "Top": {
    80	                    "readable_name": "Top",
    81	                  "code": "void Top() {}",
    82	                  "level": "upper",
    83	                  "synth": "hls",
    84	                  "ports": [],
    85	                  "tasks": {
    86	                    "Leaf": [
    87	                      {"name": "Leaf_0", "args": {}, "step": 0}
    88	                    ]
    89	                  },
    90	                  "fifos": {}
    91	                }
    92	              }
    93	            }"#,
    94	        )
    95	        .expect("graph parses");
    96	    }
    97	
    98	    #[test]
    99	    fn missing_root_target_rejected() {
   100	        // The flow target is required at the root now that it is the single
   101	        // home for the vendor flow (analyze injects it before parsing).
   102	        let err = TaskGraph::from_json(
   103	            r#"{"cflags":[],"top":"T","tasks":{"T":{"code":"","level":"upper","synth":"hls","readable_name":"T","ports":[],"tasks":{},"fifos":{}}}}"#,
   104	        )
   105	        .expect_err("missing root `target` must fail");
   106	        assert!(
   107	            err.to_string().contains("target"),
   108	            "error must point at the missing target field; got {err}",
   109	        );
   110	    }
