     1	//! Port-only RTL shells for tasks implemented through custom RTL.
     2	
     3	use tapa_ir::port::ArgCategory;
     4	use tapa_ir::Task;
     5	use tapa_protocol::{
     6	    axi_subport_width, PortDir, HANDSHAKE_CLK, HANDSHAKE_DONE, HANDSHAKE_IDLE, HANDSHAKE_READY,
     7	    HANDSHAKE_RST_N, HANDSHAKE_START, M_AXI_CHANNEL_ORDER, M_AXI_PORTS, M_AXI_PREFIX,
     8	};
     9	use tapa_rtl::module::sanitize_array_name;
    10	use tapa_rtl::mutation::{simple_port, wide_port};
    11	use tapa_rtl::port::{Direction, Port};
    12	
    13	fn port_with_width(name: impl Into<String>, direction: Direction, width: u32) -> Port {
    14	    if width > 1 {
    15	        wide_port(name, direction, &(width - 1).to_string(), "0")
    16	    } else {
    17	        simple_port(name, direction)
    18	    }
    19	}
    20	
    21	fn add_m_axi_ports(ports: &mut Vec<Port>, name: &str, data_width: u32) {
    22	    let prefix = format!("{M_AXI_PREFIX}{}", sanitize_array_name(name));
    23	    for &channel in M_AXI_CHANNEL_ORDER {
    24	        let Some(&subports) = M_AXI_PORTS.get(channel) else {
    25	            continue;
    26	        };
    27	        for &(subport, direction) in subports {
    28	            let direction = match direction {
    29	                PortDir::Input => Direction::Input,
    30	                PortDir::Output => Direction::Output,
    31	            };
    32	            let width = axi_subport_width(subport, data_width, 64, 1);
    33	            ports.push(port_with_width(
    34	                format!("{prefix}_{channel}{subport}"),
    35	                direction,
    36	                width,
    37	            ));
    38	        }
    39	    }
    40	}
    41	
    42	fn stream_names(name: &str, cat: ArgCategory, chan_count: Option<u32>) -> Vec<String> {
    43	    let name = sanitize_array_name(name);
    44	    let chan_count = chan_count.unwrap_or(1);
    45	    if matches!(cat, ArgCategory::Istreams | ArgCategory::Ostreams) && chan_count > 1 {
    46	        (0..chan_count).map(|idx| format!("{name}_{idx}")).collect()
    47	    } else {
    48	        vec![name]
    49	    }
    50	}
    51	
    52	fn add_istream_ports(ports: &mut Vec<Port>, name: &str, width: u32) {
    53	    let stream_width = width.saturating_add(1);
    54	    ports.extend([
    55	        port_with_width(format!("{name}_s_dout"), Direction::Input, stream_width),
    56	        simple_port(format!("{name}_s_empty_n"), Direction::Input),
    57	        simple_port(format!("{name}_s_read"), Direction::Output),
    58	        port_with_width(format!("{name}_peek_dout"), Direction::Input, stream_width),
    59	        simple_port(format!("{name}_peek_empty_n"), Direction::Input),
    60	        simple_port(format!("{name}_peek_read"), Direction::Output),
    61	    ]);
    62	}
    63	
    64	fn add_ostream_ports(ports: &mut Vec<Port>, name: &str, width: u32) {
    65	    let stream_width = width.saturating_add(1);
    66	    ports.extend([
    67	        port_with_width(format!("{name}_s_din"), Direction::Output, stream_width),
    68	        simple_port(format!("{name}_s_full_n"), Direction::Input),
    69	        simple_port(format!("{name}_s_write"), Direction::Output),
    70	        port_with_width(format!("{name}_peek"), Direction::Input, stream_width),
    71	    ]);
    72	}
    73	
    74	fn add_addr_ostream_ports(ports: &mut Vec<Port>, name: &str) {
    75	    ports.extend([
    76	        port_with_width(format!("{name}_s_din"), Direction::Output, 64),
    77	        simple_port(format!("{name}_s_full_n"), Direction::Input),
    78	        simple_port(format!("{name}_s_write"), Direction::Output),
    79	        port_with_width(format!("{name}_offset"), Direction::Input, 64),
    80	    ]);
    81	}
    82	
    83	fn add_async_mmap_ports(ports: &mut Vec<Port>, name: &str, data_width: u32) {
    84	    let name = sanitize_array_name(name);
    85	    add_addr_ostream_ports(ports, &format!("{name}_read_addr"));
    86	    add_istream_ports(ports, &format!("{name}_read_data"), data_width);
    87	    add_addr_ostream_ports(ports, &format!("{name}_write_addr"));
    88	    add_ostream_ports(ports, &format!("{name}_write_data"), data_width);
    89	    add_istream_ports(ports, &format!("{name}_write_resp"), 8);
    90	}
    91	
    92	fn add_mmap_ports(ports: &mut Vec<Port>, name: &str, width: u32, chan_count: Option<u32>) {
    93	    let name = sanitize_array_name(name);
    94	    if let Some(chan_count) = chan_count {
    95	        for idx in 0..chan_count {
    96	            let indexed_name = format!("{name}_{idx}");
    97	            ports.push(port_with_width(
    98	                format!("{indexed_name}_offset"),
    99	                Direction::Input,
   100	                64,
   101	            ));
   102	            add_m_axi_ports(ports, &indexed_name, width);
   103	        }
   104	    } else {
   105	        ports.push(port_with_width(
   106	            format!("{name}_offset"),
   107	            Direction::Input,
   108	            64,
   109	        ));
   110	        add_m_axi_ports(ports, &name, width);
   111	    }
   112	}
   113	
   114	/// Render the port-only Verilog module used as the starting point for a
   115	/// `target("ignore")` custom RTL implementation.
   116	#[must_use]
   117	pub fn render_task_template(name: &str, task: &Task) -> String {
   118	    let mut ports = vec![
   119	        simple_port(HANDSHAKE_CLK, Direction::Input),
   120	        simple_port(HANDSHAKE_RST_N, Direction::Input),
   121	        simple_port(HANDSHAKE_START, Direction::Input),
   122	        simple_port(HANDSHAKE_DONE, Direction::Output),
   123	        simple_port(HANDSHAKE_IDLE, Direction::Output),
   124	        simple_port(HANDSHAKE_READY, Direction::Output),
   125	    ];
   126	
   127	    for task_port in &task.ports {
   128	        match task_port.cat {
   129	            ArgCategory::Scalar => ports.push(port_with_width(
   130	                sanitize_array_name(&task_port.name),
   131	                Direction::Input,
   132	                task_port.width,
   133	            )),
   134	            ArgCategory::Istream | ArgCategory::Istreams => {
   135	                for stream in stream_names(&task_port.name, task_port.cat, task_port.chan_count) {
   136	                    add_istream_ports(&mut ports, &stream, task_port.width);
   137	                }
   138	            }
   139	            ArgCategory::Ostream | ArgCategory::Ostreams => {
   140	                for stream in stream_names(&task_port.name, task_port.cat, task_port.chan_count) {
   141	                    add_ostream_ports(&mut ports, &stream, task_port.width);
   142	                }
   143	            }
   144	            ArgCategory::AsyncMmap => {
   145	                add_async_mmap_ports(&mut ports, &task_port.name, task_port.width);
   146	            }
   147	            ArgCategory::Mmap | ArgCategory::Immap | ArgCategory::Ommap => add_mmap_ports(
   148	                &mut ports,
   149	                &task_port.name,
   150	                task_port.width,
   151	                task_port.chan_count,
   152	            ),
   153	        }
   154	    }
   155	
