    53	/// Argument / port category.
    54	///
    55	/// `"hmap"` is an alias that deserializes to `Mmap`.
    56	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, IntoStaticStr, EnumString)]
    57	#[strum(serialize_all = "snake_case")]
    58	pub enum ArgCategory {
    59	    Istream,
    60	    Ostream,
    61	    Istreams,
    62	    Ostreams,
    63	    Scalar,
    64	    #[strum(serialize = "mmap", serialize = "hmap")]
    65	    Mmap,
    66	    Immap,
    67	    Ommap,
