    70	}
    71	
    72	impl Serialize for ArgCategory {
    73	    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
    74	        serializer.serialize_str(self.as_str())
    75	    }
    76	}
    77	
    78	impl<'de> Deserialize<'de> for ArgCategory {
    79	    fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
    80	        let s = String::deserialize(deserializer)?;
    81	        Self::from_str(&s).map_err(|_| serde::de::Error::custom(format!("unknown category: {s}")))
    82	    }
    83	}
