 99	// Generate the body-preamble text for a task at the given level.
100	std::string GeneratePreamble(const Backend& backend, const TaskModel& task,
101	                             bool is_top) {
102	  CodeSink sink;
103	  for (const clang::ParmVarDecl* param : task.def->parameters()) {
104	    const PortContext p{param, ClassifyTapaType(param), task.level, is_top};
105	    backend.EmitPortPreamble(p, sink);
106	    sink.Line("");  // blank line between parameters
107	  }
108	  return sink.Str();
