111	// Vitis HLS rejects `inline` on task functions; strip the leading keyword.
112	void RemoveInline(const clang::FunctionDecl* func, clang::Rewriter& rewriter) {
113	  if (!func->isInlineSpecified()) return;
114	  clang::Token token;
115	  clang::Lexer::getRawToken(func->getBeginLoc(), token, rewriter.getSourceMgr(),
116	                            rewriter.getLangOpts());
117	  if (token.getRawIdentifier().str() == "inline") {
118	    rewriter.RemoveText(token.getLocation(), token.getLength());
119	  } else {
120	    llvm::errs() << "Warning: expected 'inline' at the start of a task; not "
121	                    "removed. Vitis HLS does not support inline tasks.\n";
122	  }
123	}
