125	// Add `#pragma HLS stream` depth pragmas after each stream declaration.
126	void RewriteStreamDefinitions(const clang::FunctionDecl* func,
127	                              clang::Rewriter& rewriter) {
128	  if (!func->hasBody()) return;
129	  for (const clang::Stmt* child : func->getBody()->children()) {
130	    const auto* decl_stmt = llvm::dyn_cast<clang::DeclStmt>(child);
131	    if (decl_stmt == nullptr || !decl_stmt->isSingleDecl()) continue;
132	    const auto* var =
133	        llvm::dyn_cast<clang::VarDecl>(decl_stmt->getSingleDecl());
