    13	
    14	namespace tapa::cc {
    15	
    16	// Everything a per-port hook needs to branch on: the parameter, its TAPA kind,
    17	// the task's level, and whether it is the top-level task. The level x category
    18	// fan-out is data here, not a method-name explosion.
    19	struct PortContext {
    20	  const clang::ParmVarDecl* param;
    21	  TapaKind kind;
    22	  TaskLevel level;
    23	  bool is_top;
    24	};
    25	
    26	// A synthesis backend (vendor). The base class owns non-virtual routers that
    27	// dispatch by kind; a vendor overrides the small per-category hooks and the
    28	// whole-task operations it needs. Vendors are grouped: one class per family
    29	// (e.g. Xilinx HLS + Vitis via a flag). RTTI-free by construction.
    30	class Backend {
    31	 public:
    32	  virtual ~Backend() = default;
    33	
    34	  // Serialized target name ("hls", "ignore", ...).
    35	  virtual std::string_view Name() const = 0;
    36	
    37	  // Router: emit the interface pragmas + anti-DCE stubs for one port.
    38	  void EmitPortPreamble(const PortContext& p, CodeSink& out) const {
    39	    if (IsStreamInterface(p.kind)) {
    40	      EmitStreamPort(p, out);
    41	    } else if (IsAsyncMmap(p.kind)) {
    42	      EmitAsyncMmapPort(p, out);
    43	    } else if (IsMmapInterface(p.kind)) {
    44	      EmitMmapPort(p, out);
    45	    } else {
    46	      EmitScalarPort(p, out);
    47	    }
    48	  }
    49	
    50	  // Whole-function operations. Signature rewriting depends on the function's
    51	  // own level (a task's TaskModel.level + whether it is the top), so it is
    52	  // applied to every task in a file, not just the current one.
    53	  //  - RewriteSignature: rewrite the parameter list (mmap -> uint64 offset,
    54	  //    Vitis stream -> qdma_axis). Applied to every task func in the file.
    55	  //  - RewriteTaskFunc: rewrite the body/shell of the *current* task (top-level
    56	  //    extern-C shell, middle-level connection shell, lower-level preamble).
    57	  //  - StripOtherTask: reduce a non-current task in this file to a signature.
    58	  //  - RewriteHelperFunc: rewrite a non-task helper function (same in every
    59	  //    file).
    60	  //  - LowerPipeline/LowerUnroll: lower a loop attribute to backend pragmas.
    61	  virtual void RewriteSignature(const TaskModel& task, bool is_top,
    62	                                clang::Rewriter& rewriter) const = 0;
    63	  virtual void RewriteTaskFunc(const TaskModel& task, bool is_top,
    64	                               clang::Rewriter& rewriter) const = 0;
    65	  virtual void StripOtherTask(const clang::FunctionDecl* func,
    66	                              clang::Rewriter& rewriter) const = 0;
    67	  virtual void RewriteHelperFunc(const clang::FunctionDecl* func,
    68	                                 clang::Rewriter& rewriter) const = 0;
    69	  virtual void LowerPipeline(int ii, const clang::Stmt* body,
    70	                             clang::Rewriter& rewriter) const = 0;
    71	  virtual void LowerUnroll(int factor, const clang::Stmt* body,
    72	                           clang::Rewriter& rewriter) const = 0;
    73	
    74	 protected:
    75	  // Per-category port hooks: a vendor overrides only what it needs; the
    76	  // defaults emit nothing.
    77	  virtual void EmitStreamPort(const PortContext&, CodeSink&) const {}
    78	  virtual void EmitMmapPort(const PortContext&, CodeSink&) const {}
    79	  virtual void EmitAsyncMmapPort(const PortContext&, CodeSink&) const {}
    80	  virtual void EmitScalarPort(const PortContext&, CodeSink&) const {}
    81	};
    82	
    83	}  // namespace tapa::cc
    84	
    85	#endif  // TAPA_CODEGEN_BACKEND_H_
