    33	  void EmitMmapPort(const PortContext&, CodeSink&) const override;
    34	  void EmitAsyncMmapPort(const PortContext&, CodeSink&) const override;
    35	  void EmitScalarPort(const PortContext&, CodeSink&) const override;
