    30	void IgnoreBackend::RewriteTaskFunc(const TaskModel& task, bool /*is_top*/,
    31	                                    clang::Rewriter& rewriter) const {
    32	  const clang::FunctionDecl* func = task.def;
    33	  if (!func->hasBody()) return;
    34	  // Replace the body with a shell of dummy port reads/writes only.
    35	  CodeSink sink;
    36	  for (const clang::ParmVarDecl* param : func->parameters()) {
    37	    EmitPortPreamble(
    38	        PortContext{param, ClassifyTapaType(param), TaskLevel::kLower, false},
    39	        sink);
    40	    sink.Line("");  // blank line between parameters (and a trailing newline)
    41	  }
    42	  rewriter.ReplaceText(func->getBody()->getSourceRange(),
    43	                       "{\n" + sink.Str() + "}\n");
    44	}
    45	
    46	void IgnoreBackend::StripOtherTask(const clang::FunctionDecl* /*func*/,
    47	                                   clang::Rewriter& /*rewriter*/) const {
    48	  // The ignore shell leaves other task functions untouched (unlike the Xilinx
    49	  // backend); only the ignored task becomes a shell and helpers are cleared.
    50	}
    51	
    52	void IgnoreBackend::RewriteHelperFunc(const clang::FunctionDecl* func,
    53	                                      clang::Rewriter& rewriter) const {
    54	  // Clear non-task helper bodies in the ignore shell.
    55	  if (func->hasBody()) {
    56	    rewriter.ReplaceText(func->getBody()->getSourceRange(), "{}\n");
    57	  }
    58	}
