    14	class FileFuncCollector : public clang::RecursiveASTVisitor<FileFuncCollector> {
    15	 public:
    16	  explicit FileFuncCollector(const clang::ASTContext& ctx) : ctx_(ctx) {}
    17	  std::vector<const clang::FunctionDecl*> funcs;
    18	
    19	  bool VisitFunctionDecl(clang::FunctionDecl* func) {
    20	    if (func->isGlobal() &&
    21	        ctx_.getSourceManager().isWrittenInMainFile(func->getLocation()) &&
    22	        func->hasBody()) {
    23	      funcs.push_back(func);
    24	    }
    25	    return true;
    26	  }
    27	
    28	 private:
    29	  const clang::ASTContext& ctx_;
    30	};
    31	
    32	}  // namespace
    33	
    34	std::vector<const clang::FunctionDecl*> CollectFileFuncs(
    35	    const clang::ASTContext& ctx) {
    36	  FileFuncCollector collector(ctx);
    37	  // TraverseDecl mutates nothing but is non-const in the API.
    38	  collector.TraverseDecl(
    39	      const_cast<clang::ASTContext&>(ctx).getTranslationUnitDecl());
    40	  return collector.funcs;
    41	}
    42	
    43	Program BuildProgram(clang::ASTContext& ctx, llvm::StringRef top,
    44	                     SynthTarget default_target) {
    45	  Program program;
    46	  program.top = top.str();
    47	  program.file_funcs = CollectFileFuncs(ctx);
    48	  program.tasks = DiscoverTasks(ctx, top, default_target, program.file_funcs);
    49	  for (auto& [name, task] : program.tasks) {
    50	    task.ports = BuildPorts(ctx, task.def);
    51	    if (task.level == TaskLevel::kUpper) {
    52	      ParseUpperTask(ctx, task, /*is_top=*/name == program.top);
    53	    }
    54	  }
    55	  return program;
