    83	bool IsIgnored(const clang::FunctionDecl* func) {
    84	  if (const auto* attr = func->getAttr<clang::TapaTargetAttr>()) {
    85	    return attr->getTarget() == clang::TapaTargetAttr::TargetType::Ignore;
    86	  }
    87	  return false;
