    90	TaskLevel LevelOf(const clang::FunctionDecl* func) {
    91	  if (!IsIgnored(func) && GetTapaTaskObject(func->getBody()) != nullptr) {
    92	    return TaskLevel::kUpper;
    93	  }
    94	  return TaskLevel::kLower;
    95	}
    96	
    97	SynthTarget ResolveTarget(const clang::FunctionDecl* func,
    98	                          SynthTarget default_target) {
    99	  const auto* attr = func->getAttr<clang::TapaTargetAttr>();
   100	  if (attr == nullptr) return default_target;
   101	  using TT = clang::TapaTargetAttr::TargetType;
   102	  switch (attr->getTarget()) {
   103	    case TT::XilinxHLS:
   104	      return SynthTarget::kXilinxHls;
   105	    case TT::XilinxVitis:
   106	      return SynthTarget::kXilinxVitis;
   107	    case TT::Ignore:
   108	      return SynthTarget::kIgnore;
   109	    default:
   110	      return default_target;
   111	  }
   112	}
   113	
   114	std::map<std::string, TaskModel> DiscoverTasks(
   115	    clang::ASTContext& ctx, llvm::StringRef top_name,
   116	    SynthTarget default_target,
   117	    llvm::ArrayRef<const clang::FunctionDecl*> file_funcs) {
   118	  // Index definitions by name so redefinitions can be detected and the top
   119	  // task located.
   120	  std::multimap<std::string, const clang::FunctionDecl*> defs;
   121	  for (const clang::FunctionDecl* f : file_funcs) {
   122	    if (f->isThisDeclarationADefinition()) {
   123	      defs.emplace(f->getNameAsString(), f);
   124	    }
   125	  }
   126	
   127	  const auto top_it = defs.find(top_name.str());
   128	  if (top_it == defs.end()) {
   129	    ReportError(ctx, {}, "top-level task '%0' not found", top_name);
   130	    return {};
   131	  }
   132	  const clang::FunctionDecl* top_func = top_it->second;
   133	  if (IsIgnored(top_func)) {
   134	    ReportError(ctx, top_func->getLocation(),
   135	                "tapa top-level task function cannot be ignored");
   136	    return {};
   137	  }
   138	
   139	  const std::unique_ptr<clang::MangleContext> mangler(
   140	      clang::ItaniumMangleContext::create(ctx, ctx.getDiagnostics()));
   141	
   142	  auto make_model = [&](const clang::FunctionDecl* func,
   143	                        const clang::FunctionDecl* invoker,
   144	                        bool is_spec) -> TaskModel {
   145	    TaskModel m;
   146	    m.def = func;
   147	    m.invoker = invoker;
   148	    m.is_template_spec = is_spec;
   149	    if (is_spec) {
   150	      m.name = MangledTaskName(*mangler, func);
   151	      m.readable_name = ReadableTaskName(ctx, func);
   152	    } else {
   153	      m.name = func->getNameAsString();
   154	      m.readable_name = m.name;
   155	    }
   156	    m.level = LevelOf(func);
   157	    m.target = ResolveTarget(func, default_target);
   158	    return m;
   159	  };
   160	
   161	  std::map<std::string, TaskModel> tasks;
   162	  std::queue<const clang::FunctionDecl*> work;
   163	
   164	  const TaskModel top_model = make_model(top_func, nullptr, /*is_spec=*/false);
   165	  tasks.emplace(top_model.name, top_model);
   166	  work.push(top_func);
   167	
   168	  while (!work.empty()) {
   169	    const clang::FunctionDecl* upper = work.front();
   170	    work.pop();
   171	    if (IsIgnored(upper)) continue;
   172	    const clang::Expr* task_obj = GetTapaTaskObject(upper->getBody());
   173	    if (task_obj == nullptr) continue;  // leaf task
   174	
   175	    for (const clang::CXXMemberCallExpr* invoke : GetInvokes(task_obj)) {
   176	      const clang::FunctionDecl* child = InvokeCallee(invoke);
   177	      if (child == nullptr || !child->isThisDeclarationADefinition()) continue;
   178	      const bool is_spec = child->isFunctionTemplateSpecialization();
   179	      TaskModel m = make_model(child, is_spec ? upper : nullptr, is_spec);
   180	      if (tasks.find(m.name) == tasks.end()) {
   181	        tasks.emplace(m.name, std::move(m));
   182	        work.push(child);
   183	      }
   184	    }
   185	  }
   186	
   187	  // A task function must have exactly one definition.
   188	  for (const auto& [name, model] : tasks) {
   189	    if (defs.count(model.def->getNameAsString()) > 1) {
   190	      ReportError(ctx, model.def->getLocation(), "task '%0' re-defined",
   191	                  model.def->getNameAsString());
   192	    }
   193	  }
   194	
   195	  return tasks;
   196	}
   197	
   198	}  // namespace tapa::cc
