    14	// name[i] — the per-channel spelling for an expanded array interface.
    15	std::string ArrayElemName(const std::string& name, uint32_t i) {
    16	  return name + "[" + std::to_string(i) + "]";
    17	}
    18	
    19	// The 0th template argument printed as a C++ type (element type), e.g.
    20	// "const float" for `tapa::mmap<const float>`. Empty if absent.
    21	std::string ElementTypeName(const clang::ParmVarDecl* param) {
    22	  if (const auto* arg = GetTemplateArg(param->getType(), 0)) {
    23	    return TemplateArgName(*arg);
    24	  }
    25	  return "";
    26	}
    27	
    28	// Bit width of the element (0th template arg) type, or 0 if absent.
    29	uint32_t ElementWidth(const clang::ASTContext& ctx,
    30	                      const clang::ParmVarDecl* param) {
    31	  if (const auto* arg = GetTemplateArg(param->getType(), 0)) {
    32	    if (arg->getKind() == clang::TemplateArgument::Type) {
    33	      return BitWidth(ctx, arg->getAsType());
    34	    }
    35	  }
    36	  return 0;
    37	}
    38	
    39	// An integral template argument at `idx` as a channel count, or nullopt.
    40	std::optional<uint32_t> IntArg(const clang::ParmVarDecl* param, unsigned idx) {
    41	  if (const auto n = IntTemplateArg(param->getType(), idx)) {
    42	    return static_cast<uint32_t>(*n);
    43	  }
    44	  return std::nullopt;
    45	}
    46	
    47	}  // namespace
    48	
    49	std::vector<Port> BuildPorts(const clang::ASTContext& ctx,
    50	                             const clang::FunctionDecl* task) {
    51	  std::vector<Port> ports;
    52	  for (const clang::ParmVarDecl* param : task->parameters()) {
    53	    const TapaKind kind = ClassifyTapaType(param);
    54	    const std::string name = param->getNameAsString();
    55	    const std::string elem = ElementTypeName(param);
    56	    const uint32_t elem_width = ElementWidth(ctx, param);
    57	
    58	    switch (kind) {
    59	      case TapaKind::kMmap:
    60	      case TapaKind::kImmap:
    61	      case TapaKind::kOmmap:
    62	      case TapaKind::kAsyncMmap:
    63	        ports.push_back(Port{name, kind, elem + "*", elem_width, std::nullopt,
    64	                             std::nullopt});
    65	        break;
    66	
    67	      case TapaKind::kMmaps: {
    68	        // Expand to one `mmap` port per channel (name[i]).
    69	        const uint32_t n = IntArg(param, 1).value_or(0);
    70	        for (uint32_t i = 0; i < n; ++i) {
    71	          ports.push_back(Port{ArrayElemName(name, i), TapaKind::kMmap,
    72	                               elem + "*", elem_width, std::nullopt,
    73	                               std::nullopt});
    74	        }
    75	        break;
    76	      }
    77	
    78	      case TapaKind::kHmap:
    79	        ports.push_back(Port{name, kind, elem + "*", elem_width,
    80	                             IntArg(param, 1), IntArg(param, 2)});
    81	        break;
    82	
    83	      case TapaKind::kIStream:
    84	      case TapaKind::kOStream:
    85	        ports.push_back(
    86	            Port{name, kind, elem, elem_width, std::nullopt, std::nullopt});
    87	        break;
    88	
    89	      case TapaKind::kIStreams:
    90	      case TapaKind::kOStreams:
    91	        ports.push_back(
    92	            Port{name, kind, elem, elem_width, IntArg(param, 1), std::nullopt});
    93	        break;
    94	
    95	      default:
    96	        // Scalar: the parameter's own type and width.
    97	        ports.push_back(
    98	            Port{name, TapaKind::kNotTapa, param->getType().getAsString(),
    99	                 BitWidth(ctx, param->getType()), std::nullopt, std::nullopt});
   100	        break;
   101	    }
   102	  }
   103	  return ports;
   104	}
   105	
   106	}  // namespace tapa::cc

