    45	// step (bulk-synchronous mode), vector length, and whether an explicit instance
    46	// name is present, from the invoke method's template specialization arguments.
    47	struct InvokeMode {
    48	  int64_t step = 0;
    49	  uint64_t vec_length = 1;
    50	  bool has_name = false;
    51	};
    52	
    53	InvokeMode GetInvokeMode(const clang::CXXMemberCallExpr* invoke) {
    54	  InvokeMode mode;
    55	  const auto* method =
    56	      llvm::dyn_cast_or_null<clang::CXXMethodDecl>(invoke->getCalleeDecl());
    57	  if (method == nullptr) return mode;
    58	  const auto* spec_args = method->getTemplateSpecializationArgs();
    59	  if (spec_args == nullptr) return mode;
    60	  const auto args = spec_args->asArray();
    61	  using TA = clang::TemplateArgument;
    62	  if (!args.empty() && args[0].getKind() == TA::Integral) {
    63	    mode.step = args[0].getAsIntegral().getSExtValue();
    64	  }
    65	  if (args.size() > 1 && args[1].getKind() == TA::Integral) {
    66	    mode.vec_length = args[1].getAsIntegral().getZExtValue();
    67	  }
    68	  if (!args.empty() && args.back().getKind() == TA::Integral) {
    69	    mode.has_name = true;
    70	  }
    71	  return mode;
    72	}
