    78	  for (const Port& port : task.ports) {
    79	    if (port.name != base) continue;
    80	    switch (port.kind) {
    81	      case TapaKind::kIStream:
    82	      case TapaKind::kOStream:
    83	      case TapaKind::kIStreams:
    84	      case TapaKind::kOStreams:
    85	        return true;
    86	      default:
    87	        return false;
    88	    }
    89	  }
    90	  return false;
