    93	// Look up a stream argument in `task.streams`; for the top task, a stream
    94	// argument that names one of the task's own ports (rather than a locally
    95	// declared FIFO) yields a fresh depth-less entry — an external FIFO whose
    96	// other endpoint is the kernel boundary.
    97	std::map<std::string, StreamDecl>::iterator FindOrExternalStream(
    98	    TaskModel& task, const std::string& arg, bool is_top) {
