   111	void ParseUpperTask(clang::ASTContext& ctx, TaskModel& task, bool is_top) {
   112	  const clang::FunctionDecl* func = task.def;
   113	  if (func == nullptr || !func->hasBody()) return;
   114	  const clang::Expr* task_obj = GetTapaTaskObject(func->getBody());
   115	  if (task_obj == nullptr) return;  // leaf task
   116	
   117	  const std::unique_ptr<clang::MangleContext> mangler(
   118	      clang::ItaniumMangleContext::create(ctx, ctx.getDiagnostics()));
   119	
   120	  // --- 1. Stream (FIFO) declarations. ---
   121	  for (const clang::Stmt* child : func->getBody()->children()) {
   122	    const auto* decl_stmt = llvm::dyn_cast<clang::DeclStmt>(child);
   123	    if (decl_stmt == nullptr || !decl_stmt->isSingleDecl()) continue;
   124	    const auto* var =
   125	        llvm::dyn_cast<clang::VarDecl>(decl_stmt->getSingleDecl());
   126	    if (var == nullptr) continue;
   127	    const std::string name = var->getNameAsString();
   128	    switch (ClassifyTapaType(var->getType())) {
   129	      case TapaKind::kStream:
   130	        task.streams[name] =
   131	            StreamDecl{static_cast<uint64_t>(
   132	                           IntTemplateArg(var->getType(), 1).value_or(0)),
   133	                       var, std::nullopt, std::nullopt};
   134	        break;
   135	      case TapaKind::kStreams: {
   136	        const uint64_t depth = IntTemplateArg(var->getType(), 2).value_or(0);
   137	        const int64_t n = IntTemplateArg(var->getType(), 1).value_or(0);
   138	        for (int64_t i = 0; i < n; ++i) {
   139	          task.streams[ArrayNameAt(name, i)] =
   140	              StreamDecl{depth, var, std::nullopt, std::nullopt};
   141	        }
   142	        break;
   143	      }
   144	      default:
   145	        break;
   146	    }
   147	  }
   148	
   149	  // --- 2. Invocations. ---
   150	  // Access positions distribute an array argument (streams/mmaps) across the
   151	  // scalar ports it feeds, in order of appearance.
   152	  std::map<std::string, int> istreams_pos;
   153	  std::map<std::string, int> ostreams_pos;
   154	  std::map<std::string, int> mmaps_pos;
   155	  std::map<const clang::Expr*, int> seq_pos;
   156	
   157	  for (const clang::CXXMemberCallExpr* invoke : GetInvokes(task_obj)) {
   158	    const InvokeMode mode = GetInvokeMode(invoke);
   159	    bool has_executable = false;
   160	    std::string task_name;
   161	    const clang::FunctionDecl* callee = nullptr;
   162	
   163	    // Map an array argument to its i-th element name (wrapping on the array
   164	    // length); a scalar argument is returned unchanged.
   165	    auto array_element = [&](const std::string& name, int pos,
   166	                             const clang::DeclRefExpr* ref) -> std::string {
   167	      if (ref == nullptr) return name;
   168	      const TapaKind rk = ClassifyTapaType(ref->getType());
   169	      if (rk == TapaKind::kMmaps || rk == TapaKind::kIStreams ||
   170	          rk == TapaKind::kOStreams || rk == TapaKind::kStreams) {
   171	        const int64_t len = IntTemplateArg(ref->getType(), 1).value_or(0);
   172	        if (len <= 0) return name;
   173	        return ArrayNameAt(name, pos % len);
   174	      }
   175	      return name;
   176	    };
   177	
   178	    for (uint64_t i_vec = 0; i_vec < mode.vec_length; ++i_vec) {
   179	      for (unsigned i = 0; i < invoke->getNumArgs(); ++i) {
   180	        const clang::Expr* arg = invoke->getArg(i);
   181	
   182	        if (ClassifyTapaType(arg->getType()) == TapaKind::kExecutable) {
   183	          has_executable = true;
   184	          continue;
   185	        }
   186	
   187	        const auto* decl_ref = llvm::dyn_cast<clang::DeclRefExpr>(arg);
   188	        const auto* mat = llvm::dyn_cast<clang::MaterializeTemporaryExpr>(arg);
   189	        const auto* op_call =
   190	            mat ? llvm::dyn_cast<clang::CXXOperatorCallExpr>(mat->getSubExpr())
   191	                : nullptr;
   192	        const bool is_seq = ClassifyTapaType(arg->getType()) == TapaKind::kSeq;
   193	        const std::optional<int64_t> as_int = EvalInt(ctx, arg);
   194	        const bool is_int_literal =
   195	            !decl_ref && !op_call && !is_seq && as_int.has_value();
   196	
   197	        std::string arg_name;
   198	        if (decl_ref != nullptr) {
   199	          arg_name = decl_ref->getNameInfo().getAsString();
   200	        } else if (op_call != nullptr) {
   201	          const auto* base = llvm::dyn_cast<clang::DeclRefExpr>(
   202	              op_call->getArg(0)->IgnoreImplicit());
   203	          const int64_t idx = EvalInt(ctx, op_call->getArg(1)).value_or(0);
   204	          if (base != nullptr) {
   205	            arg_name = ArrayNameAt(base->getNameInfo().getAsString(), idx);
   206	          }
   207	        } else if (is_int_literal) {
   208	          arg_name = "64'd" + std::to_string(static_cast<uint64_t>(*as_int));
