   236	          std::vector<Instance>& insts = task.instances[task_name];
   237	          const uint32_t inst_index = static_cast<uint32_t>(insts.size() - 1);
   238	
   239	          auto set_arg = [&](const std::string& a, const std::string& p,
   240	                             TapaKind cat) {
   241	            insts.back().args[p] = Arg{a, cat};
   242	          };
