   249	            }
   250	            it->second.consumed_by = Endpoint{task_name, inst_index};
   251	          };
   252	          auto mark_producer = [&](const std::string& a) {
   253	            auto it = FindOrExternalStream(task, a, is_top);
   254	            if (it == task.streams.end()) return;
   255	            if (it->second.produced_by.has_value()) {
   256	              Report(ctx, clang::DiagnosticsEngine::Error, arg->getBeginLoc(),
   257	                     "tapa::stream '%0' produced more than once", a);
