   270	            set_arg(a, port, TapaKind::kIStream);
   271	          } else if (pk == TapaKind::kOStream) {
   272	            const std::string a =
   273	                array_element(arg_name, ostreams_pos[arg_name]++, decl_ref);
   274	            mark_producer(a);
   275	            set_arg(a, port, TapaKind::kOStream);
   276	          } else if (pk == TapaKind::kIStreams) {
   277	            const int64_t n = IntTemplateArg(param->getType(), 1).value_or(0);
   278	            for (int64_t j = 0; j < n; ++j) {
   279	              const std::string a =
   280	                  array_element(arg_name, istreams_pos[arg_name]++, decl_ref);
   281	              mark_consumer(a);
   282	              set_arg(a, ArrayNameAt(port, j), TapaKind::kIStream);
   283	            }
   284	          } else if (pk == TapaKind::kOStreams) {
   285	            const int64_t n = IntTemplateArg(param->getType(), 1).value_or(0);
   286	            for (int64_t j = 0; j < n; ++j) {
   287	              const std::string a =
   288	                  array_element(arg_name, ostreams_pos[arg_name]++, decl_ref);
   289	              mark_producer(a);
   290	              set_arg(a, ArrayNameAt(port, j), TapaKind::kOStream);
   291	            }
   292	          } else if (is_seq) {
   293	            set_arg("64'd" + std::to_string(seq_pos[arg]++), port,
   294	                    TapaKind::kNotTapa);
   295	          } else {
   296	            set_arg(arg_name, port, TapaKind::kNotTapa);  // scalar
   297	          }
   298	          continue;
   299	        }
   300	
   301	        if (const auto* str = llvm::dyn_cast<clang::StringLiteral>(arg)) {
   302	          if (i == 1 && mode.has_name && !task_name.empty()) {
   303	            task.instances[task_name].back().name = str->getString().str();
   304	            continue;
   305	          }
   306	        }
   307	
   308	        Report(ctx, clang::DiagnosticsEngine::Error, arg->getBeginLoc(),
   309	               "unexpected argument: %0", arg->getStmtClassName());
   310	      }
   311	    }
   312	  }
   313	
   314	  // --- 3. Stream validation. ---
   315	  for (auto it = task.streams.begin(); it != task.streams.end();) {
   316	    if (it->second.decl == nullptr) {
   317	      // External top-level stream port: exactly one endpoint by construction
   318	      // (the other side is the kernel boundary), so nothing to validate.
   319	      ++it;
   320	      continue;
   321	    }
   322	    const bool produced = it->second.produced_by.has_value();
   323	    const bool consumed = it->second.consumed_by.has_value();
   324	    const clang::SourceLocation loc = it->second.decl != nullptr
   325	                                          ? it->second.decl->getBeginLoc()
   326	                                          : clang::SourceLocation();
   327	    if (!produced && !consumed) {
   328	      Report(ctx, clang::DiagnosticsEngine::Warning, loc, "unused stream: %0",
   329	             it->first);
   330	      it = task.streams.erase(it);
   331	    } else {
   332	      if (produced != consumed) {
   333	        if (consumed) {
   334	          Report(ctx, clang::DiagnosticsEngine::Error, loc,
   335	                 "consumed but not produced stream: %0", it->first);
   336	        } else {
   337	          Report(ctx, clang::DiagnosticsEngine::Error, loc,
   338	                 "produced but not consumed stream: %0", it->first);
   339	        }
   340	      }
   341	      ++it;
   342	    }
   343	  }
   344	}
