    11	namespace tapa::cc {
    12	
    13	// Emit the self-contained vendor C++ for one task: the task itself fully
    14	// rewritten (signature + body/shell), every other task reduced to a signature,
    15	// non-task helpers rewritten, and loop attributes lowered to backend pragmas.
    16	// A single pass over the model drives one clang::Rewriter -- no per-task
    17	// re-traversal of the AST. Returns the rewritten main-file text.
    18	std::string EmitTaskCode(const Program& program, const TaskModel& task,
    19	                         const Backend& backend, clang::ASTContext& ctx);
    20	
    21	}  // namespace tapa::cc
