     1	#include "rewrite.h"
     2	
     3	#include <set>
     4	#include <string>
     5	
     6	#include "clang/AST/Attr.h"
     7	#include "clang/AST/Decl.h"
     8	#include "clang/AST/Stmt.h"
     9	#include "clang/AST/StmtCXX.h"
    10	#include "clang/Basic/SourceManager.h"
    11	#include "clang/Rewrite/Core/Rewriter.h"
