    17	
    18	namespace tapa::cc {
    19	
    20	namespace {
    21	
    22	// The body of a loop statement, or nullptr if it is not a loop.
    23	const clang::Stmt* GetLoopBody(const clang::Stmt* stmt) {
    24	  if (stmt == nullptr) return nullptr;
    25	  if (const auto* s = llvm::dyn_cast<clang::DoStmt>(stmt)) return s->getBody();
    26	  if (const auto* s = llvm::dyn_cast<clang::ForStmt>(stmt)) return s->getBody();
    27	  if (const auto* s = llvm::dyn_cast<clang::WhileStmt>(stmt)) {
    28	    return s->getBody();
    29	  }
    30	  if (const auto* s = llvm::dyn_cast<clang::CXXForRangeStmt>(stmt)) {
    31	    return s->getBody();
    32	  }
    33	  return nullptr;
    34	}
    35	
    36	// Lower every [[tapa::pipeline]] / [[tapa::unroll]] attribute in a function
    37	// body to backend pragmas and remove the attribute text. Walks only this body.
    38	void LowerLoopAttrs(const clang::Stmt* stmt, const Backend& backend,
    39	                    clang::Rewriter& rewriter) {
    40	  if (stmt == nullptr) return;
    41	  for (const clang::Stmt* child : stmt->children()) {
    42	    LowerLoopAttrs(child, backend, rewriter);
    43	  }
    44	  const auto* attributed = llvm::dyn_cast<clang::AttributedStmt>(stmt);
    45	  if (attributed == nullptr) return;
    46	  const clang::Stmt* body = GetLoopBody(attributed->getSubStmt());
    47	  for (const clang::Attr* attr : attributed->getAttrs()) {
    48	    if (const auto* pipeline = llvm::dyn_cast<clang::TapaPipelineAttr>(attr)) {
    49	      backend.LowerPipeline(pipeline->getII(), body, rewriter);
    50	      RemoveLoweredAttr(rewriter, attr->getRange());
    51	    } else if (const auto* unroll =
    52	                   llvm::dyn_cast<clang::TapaUnrollAttr>(attr)) {
    53	      backend.LowerUnroll(unroll->getFactor(), body, rewriter);
    54	      RemoveLoweredAttr(rewriter, attr->getRange());
    55	    }
    56	  }
    57	}
    58	
    59	}  // namespace
    60	
    61	// The primary-template pattern of a template-specialization task's definition
    62	// (the decl that actually appears in the source), or nullptr.
    63	const clang::FunctionDecl* SpecPrimary(const TaskModel& model) {
    64	  if (!model.is_template_spec || model.def == nullptr) return nullptr;
    65	  const clang::FunctionDecl* pattern =
    66	      model.def->getTemplateInstantiationPattern();
    67	  return pattern != nullptr ? pattern->getCanonicalDecl() : nullptr;
    68	}
    69	
    70	std::string EmitTaskCode(const Program& program, const TaskModel& task,
    71	                         const Backend& backend, clang::ASTContext& ctx) {
    72	  clang::Rewriter rewriter(ctx.getSourceManager(), ctx.getLangOpts());
    73	
    74	  // The source decls that are template patterns for some task specialization,
    75	  // and the pattern for the current task (if it is a specialization). These
    76	  // primaries appear as functions in the file but are keyed in program.tasks by
    77	  // mangled name, so they are handled here rather than as helpers.
    78	  std::set<const clang::FunctionDecl*> spec_primaries;
    79	  for (const auto& [name, model] : program.tasks) {
    80	    if (const clang::FunctionDecl* primary = SpecPrimary(model)) {
    81	      spec_primaries.insert(primary);
    82	    }
    83	  }
    84	  const clang::FunctionDecl* current_primary = SpecPrimary(task);
    85	
    86	  // Non-template task functions: signature rewritten per level; current task
    87	  // keeps a rewritten body, the rest become signatures.
    88	  for (const auto& [name, model] : program.tasks) {
    89	    if (model.is_template_spec) continue;  // reached via its primary below
    90	    const bool is_top = name == program.top;
    91	    backend.RewriteSignature(model, is_top, rewriter);
    92	    if (name == task.name) {
    93	      backend.RewriteTaskFunc(model, is_top, rewriter);
    94	      LowerLoopAttrs(model.def->getBody(), backend, rewriter);
    95	    } else {
    96	      backend.StripOtherTask(model.def, rewriter);
    97	    }
    98	  }
    99	
   100	  // Remaining source functions: template-task primaries and plain helpers.
   101	  for (const clang::FunctionDecl* func : program.file_funcs) {
   102	    if (program.tasks.count(func->getNameAsString()) != 0 &&
   103	        !program.tasks.at(func->getNameAsString()).is_template_spec) {
   104	      continue;  // a non-template task, already handled above
   105	    }
   106	    const clang::FunctionDecl* canonical = func->getCanonicalDecl();
   107	    if (spec_primaries.count(canonical) != 0) {
   108	      // A template primary whose specialization(s) are tasks.
   109	      if (current_primary != nullptr && canonical == current_primary) {
   110	        // Rewrite the primary template using its OWN parameters: a bare
   111	        // template-parameter type (e.g. `tapa_mmap_type mmap`) is classified as
   112	        // a scalar here (no interface pragma) -- only the concrete wrapper
   113	        // does.
   114	        TaskModel primary = task;
   115	        primary.def = func;
   116	        backend.RewriteTaskFunc(primary, /*is_top=*/false, rewriter);
   117	        LowerLoopAttrs(func->getBody(), backend, rewriter);
   118	      } else {
   119	        backend.StripOtherTask(func, rewriter);
   120	      }
   121	    } else if (GetTapaTaskObject(func->getBody()) != nullptr) {
   122	      // Unreachable upper-level task: discovery is reachability-based, so it
   123	      // is not in program.tasks, but its body still invokes sub-tasks and
   124	      // would no longer type-check against their rewritten signatures. Strip
   125	      // it like any non-current task.
   126	      TaskModel model;
   127	      model.def = func;
   128	      model.level = TaskLevel::kUpper;
   129	      backend.RewriteSignature(model, /*is_top=*/false, rewriter);
   130	      backend.StripOtherTask(func, rewriter);
   131	    } else {
   132	      backend.RewriteHelperFunc(func, rewriter);
   133	      LowerLoopAttrs(func->getBody(), backend, rewriter);
   134	    }
   135	  }
   136	
   137	  // Emit the mangled wrapper for the current specialization after its invoker.
   138	  if (task.is_template_spec) {
   139	    InsertWrapper(task, backend, ctx, rewriter);
   140	  }
   141	
   142	  const clang::SourceManager& sm = ctx.getSourceManager();
   143	  const clang::FileID main_file = sm.getMainFileID();
   144	  const llvm::RewriteBuffer* buffer = rewriter.getRewriteBufferFor(main_file);
   145	  if (buffer == nullptr) {
   146	    return sm.getBufferData(main_file).str();  // no edits
   147	  }
   148	  return std::string(buffer->begin(), buffer->end());
   149	}
   150	
   151	}  // namespace tapa::cc
