    10	
    11	namespace tapa::cc {
    12	
    13	namespace {
    14	
    15	// Element (0th template arg) type spelling of a stream/mmap, e.g. "float".
    16	std::string ElementType(const clang::ParmVarDecl* param) {
    17	  if (const auto* arg = GetTemplateArg(param->getType(), 0)) {
    18	    return TemplateArgName(*arg);
    19	  }
    20	  return "";
    21	}
    22	
    23	// Element bit width, or 0.
    24	uint32_t ElementWidth(const clang::ParmVarDecl* param) {
    25	  if (const auto* arg = GetTemplateArg(param->getType(), 0)) {
    26	    if (arg->getKind() == clang::TemplateArgument::Type) {
    27	      return BitWidth(param->getASTContext(), arg->getAsType());
    28	    }
    29	  }
    30	  return 0;
    31	}
    32	
    33	// Channel count of an array interface, or 0.
    34	int64_t ArraySize(const clang::ParmVarDecl* param) {
    35	  return IntTemplateArg(param->getType(), 1).value_or(0);
    36	}
    37	
    38	}  // namespace
    39	
    40	void EmitDummyStreamRW(const clang::ParmVarDecl* param, TapaKind kind,
    41	                       CodeSink& out, bool qdma) {
    42	  const std::string name = param->getNameAsString();
    43	
    44	  auto dummy_read = [&](const std::string& n) {
    45	    out.Line("{ auto val = " + n + ".read(); }");
    46	    if (!qdma) {  // non-qdma streams support peek
    47	      out.Line("{ auto val = " + n + ".peek(nullptr); }");
    48	    }
    49	  };
    50	  auto dummy_write = [&](const std::string& n, const std::string& type) {
    51	    out.Line(n + ".write(" + type + "());");
    52	  };
    53	
    54	  switch (kind) {
    55	    case TapaKind::kIStream:
    56	      dummy_read(name);
    57	      break;
    58	    case TapaKind::kOStream: {
    59	      std::string type = ElementType(param);
    60	      if (qdma) {
    61	        type =
    62	            "qdma_axis<" + std::to_string(ElementWidth(param)) + ", 0, 0, 0>";
    63	      }
    64	      dummy_write(name, type);
    65	      break;
    66	    }
    67	    case TapaKind::kIStreams:
    68	      if (qdma) {
    69	        out.Line("#error istreams not supported for qdma-based tasks");
    70	      } else {
    71	        for (int64_t i = 0; i < ArraySize(param); ++i) {
    72	          dummy_read(ArrayNameAt(name, static_cast<int>(i)));
    73	        }
    74	      }
    75	      break;
    76	    case TapaKind::kOStreams:
    77	      if (qdma) {
    78	        out.Line("#error ostreams not supported for qdma-based tasks");
    79	      } else {
    80	        const std::string type = ElementType(param);
    81	        for (int64_t i = 0; i < ArraySize(param); ++i) {
    82	          dummy_write(ArrayNameAt(name, static_cast<int>(i)), type);
    83	        }
    84	      }
    85	      break;
    86	    default:
    87	      break;
    88	  }
    89	}
    90	
    91	void EmitDummyMmapOrScalarRW(const clang::ParmVarDecl* param, TapaKind kind,
    92	                             CodeSink& out) {
    93	  const std::string name = param->getNameAsString();
    94	  if (kind == TapaKind::kMmaps || kind == TapaKind::kHmap) {
    95	    for (int64_t i = 0; i < ArraySize(param); ++i) {
    96	      out.Line("{ auto val = reinterpret_cast<volatile uint8_t&>(" +
    97	               ArrayElemOffset(name, static_cast<int>(i)) + "); }");
    98	    }
    99	  } else {
   100	    const std::string ref = kind == TapaKind::kMmap ? OffsetName(name) : name;
   101	    const std::string qual =
   102	        param->getType().isConstQualified() ? "const " : "";
   103	    out.Line("{ auto val = reinterpret_cast<volatile " + qual + "uint8_t&>(" +
   104	             ref + "); }");
   105	  }
   106	}
   107	
   108	void AddPragmaToBody(clang::Rewriter& rewriter, const clang::Stmt* body,
   109	                     const std::string& pragma) {
   110	  if (const auto* compound = llvm::dyn_cast<clang::CompoundStmt>(body)) {
   111	    rewriter.InsertTextAfterToken(compound->getLBracLoc(),
   112	                                  "\n#pragma " + pragma + "\n");
   113	  } else {
   114	    rewriter.InsertTextBefore(body->getBeginLoc(),
   115	                              "_Pragma(\"" + pragma + "\")");
   116	  }
   117	}
   118	
   119	void AddPragmaAfterStmt(clang::Rewriter& rewriter, const clang::Stmt* stmt,
   120	                        const std::string& pragma) {
   121	  rewriter.InsertTextAfterToken(stmt->getEndLoc(),
   122	                                "\n#pragma " + pragma + "\n");
   123	}
   124	
   125	void RemoveLoweredAttr(clang::Rewriter& rewriter,
   126	                       clang::SourceRange attr_range) {
   127	  auto begin = attr_range.getBegin();
   128	  auto end = attr_range.getEnd();
   129	  auto at = [&](clang::SourceLocation a, clang::SourceLocation b) {
   130	    return rewriter.getRewrittenText(clang::SourceRange(a, b));
   131	  };
   132	  auto is_space = [&](const std::string& s) {
   133	    return s.empty() || std::isspace(static_cast<unsigned char>(s[0]));
   134	  };
   135	  auto is_alpha = [&](const std::string& s) {
   136	    return !s.empty() && std::isalpha(static_cast<unsigned char>(s[0]));
   137	  };
   138	
   139	  // Find the true end of the token.
   140	  for (; is_alpha(at(end.getLocWithOffset(1), end.getLocWithOffset(1)));
   141	       end = end.getLocWithOffset(1)) {
   142	  }
   143	  // Swallow surrounding whitespace.
   144	  for (; is_space(at(begin.getLocWithOffset(-1), begin.getLocWithOffset(-1)));
   145	       begin = begin.getLocWithOffset(-1)) {
   146	  }
   147	  for (; is_space(at(end.getLocWithOffset(1), end.getLocWithOffset(1)));
   148	       end = end.getLocWithOffset(1)) {
   149	  }
