   115	    if (mode == InvokeMode::kSequential) {
   116	      std::move(functor)();
   117	    } else {
   118	      schedule(mode == InvokeMode::kDetach, std::move(functor));
   119	    }
   120	  }
   121	
   122	  template <typename... Args>
   123	  static int64_t invoke(F&& f, const std::string& bitstream, Args&&... args) {
   124	    if (bitstream.empty()) {
   125	      LOG(INFO) << "running software simulation with TAPA library";
   126	      const auto tic = std::chrono::steady_clock::now();
   127	      f(std::forward<Args>(args)...);
   128	      const auto toc = std::chrono::steady_clock::now();
   129	      return std::chrono::duration_cast<std::chrono::nanoseconds>(toc - tic)
   130	          .count();
   131	    } else {
   132	      return invoke_frt(f, bitstream, std::forward<Args>(args)...);
   133	    }
   134	  }
   135	
   136	  template <typename Func, size_t... Is, typename... CapturedArgs>
   137	  static void set_fpga_args(frt::Instance& instance, Func&& func,
   138	                            std::index_sequence<Is...>,
   139	                            CapturedArgs&&... args) {
   140	    int idx = 0;
   141	    (accessor<std::tuple_element_t<Is, Params>, CapturedArgs>::access(
   142	         instance, idx, std::forward<CapturedArgs>(args)),
   143	     ...);
   144	  }
   145	
   146	 private:
   147	  template <typename... Args>
   148	  static int64_t invoke_frt(F&& f, const std::string& bitstream,
   149	                            Args&&... args) {
   150	    auto instance = frt::Instance(bitstream);
   151	
   152	    // Register SIGINT handler to kill the kernel.
   153	    CHECK(frt_sync_kernel_instance == nullptr)
   154	        << "kernel instance already exists";
   155	    frt_sync_kernel_instance = &instance;
   156	    signal(SIGINT, &kill_frt_sync_kernel);
   157	
   158	    set_fpga_args(instance, std::forward<F>(f),
   159	                  std::index_sequence_for<Args...>{},
   160	                  std::forward<Args>(args)...);
   161	    instance.WriteToDevice();
   162	    instance.Exec();
   163	    instance.ReadFromDevice();
   164	    instance.Finish();
   165	
   166	    // Unregister SIGINT handler.
   167	    signal(SIGINT, SIG_DFL);
   168	    CHECK(frt_sync_kernel_instance == &instance) << "kernel instance mismatch";
   169	    frt_sync_kernel_instance = nullptr;
   170	
   171	    return instance.ComputeTimeNanoSeconds();
   172	  }
   173	
   174	  template <typename Func, size_t... Is, typename... CapturedArgs>
   175	  static auto functor_with_accessors(bool is_sequential, Func&& func,
   176	                                     std::index_sequence<Is...>,
   177	                                     CapturedArgs&&... args) {
   178	    // Aggregate initialization evaluates args left-to-right; std::bind copies.
   179	    return binder{
   180	        func, accessor<std::tuple_element_t<Is, Params>, CapturedArgs>::access(
   181	                  std::forward<CapturedArgs>(args), is_sequential)...}
   182	        .result;
   183	  }
   184	};
