    14	/// Level of a task in the hierarchy.
    15	#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
    16	#[serde(rename_all = "lowercase")]
    17	pub enum TaskLevel {
    18	    Lower,
    19	    Upper,
    20	}
    21	
    22	/// A single task in the unified task graph.
    23	///
    24	/// The tapacc output and the post-synthesis design share this one type:
    25	/// analyze emits the structural fields, synth populates the post-synthesis
    26	/// annotation block (`clock_period`, `self_area`, `total_area`) in place,
    27	/// and report reads them back. The annotations are absent in tapacc output
    28	/// and omitted from the wire form until populated.
    29	#[allow(
    30	    clippy::derive_partial_eq_without_eq,
    31	    reason = "area dicts hold serde_json::Value, which is not Eq (Number may be f64)"
    32	)]
    33	#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
    34	#[serde(deny_unknown_fields)]
    35	pub struct Task {
    36	    /// Task level: `"lower"` (leaf) or `"upper"` (composite).
    37	    pub level: TaskLevel,
    38	    /// C++ source code for this task.
    39	    pub code: String,
    40	    /// Human-readable task name emitted by `tapacc` (e.g. the demangled
    41	    /// template specialization). Required: `tapacc` emits it unconditionally
    42	    /// for every task, equal to the task name for non-template tasks.
    43	    pub readable_name: String,
    44	    /// Per-task synthesis policy (`"hls"` / `"ignore"`).
    45	    pub synth: SynthTarget,
    46	    /// External ports / interface definitions.
    47	    #[serde(default)]
    48	    pub ports: Vec<Port>,
    49	    /// Child task instantiations (upper tasks only).
    50	    /// Maps task definition name → list of instantiations.
    51	    #[serde(default)]
    52	    pub tasks: BTreeMap<String, Vec<TaskInstance>>,
    53	    /// FIFO / interconnect definitions (upper tasks only).
    54	    #[serde(default)]
    55	    pub fifos: BTreeMap<String, InterconnectDefinition>,
    56	    /// Post-synthesis achieved clock-period estimate (seconds, stringified).
    57	    /// Seeded empty by analyze, written by synth, read by report.
    58	    #[serde(default, skip_serializing_if = "String::is_empty")]
    59	    pub clock_period: String,
    60	    /// Per-task self area dict (resource → number). Post-synthesis.
    61	    #[serde(default, skip_serializing_if = "IndexMap::is_empty")]
    62	    pub self_area: IndexMap<String, Value>,
    63	    /// Per-task total area dict (self + descendants). Post-synthesis.
    64	    #[serde(default, skip_serializing_if = "IndexMap::is_empty")]
    65	    pub total_area: IndexMap<String, Value>,
    66	}
