     1	//! The persisted pipeline state: [`WorkState`], the root of `tapa.json`.
     2	//!
     3	//! This is the *schema* half of the work-directory state file; the file I/O
     4	//! (atomic write, path helpers, the stale-work-dir error) belongs to
     5	//! `tapa-cli`, which owns the work directory. The types live here because
     6	//! `tapa.json` has two readers in two Cargo workspaces:
     7	//!
     8	//! * `tapa-cli` writes `<work_dir>/tapa.json` (`analyze`), annotates it in
     9	//!   place (`synth`), and reads it back (`pack`); and
    10	//! * `frt-cosim` reads the `tapa.json` entry `tapa pack` copies verbatim into
    11	//!   the `.zip` archive, to recover the kernel's argument list.
    12	//!
    13	//! Both parse *these* types, so a field rename is a compile error on both
    14	//! sides of the workspace boundary rather than a runtime surprise in cosim.
    15	
    16	use serde::{Deserialize, Serialize};
    17	
    18	use crate::error::ParseError;
    19	use crate::floorplan::FloorplanResult;
    20	use crate::graph::TaskGraph;
    21	
    22	/// Name of the single state file: `<work_dir>/tapa.json`, copied under the
    23	/// same name to the root of the `.zip` archive `tapa pack` emits.
    24	pub const FILE_NAME: &str = "tapa.json";
    25	
    26	/// Schema version stamped into every [`WorkState`] this tapa writes.
    27	///
    28	/// Bump on any backward-incompatible change to the state shape — including
    29	/// the nested [`TaskGraph`] wire form. Work dirs outlive tool versions, so a
    30	/// mismatch must surface as a clear "re-run analyze" error, not as a
    31	/// confusing field-level parse failure.
    32	///
    33	/// v2 added the optional [`WorkState::floorplan`] contract; v3 made routed
    34	/// channel identities variant-specific.
    35	pub const VERSION: u32 = 3;
    36	
    37	/// Everything the pipeline persists between steps.
    38	#[allow(
    39	    clippy::derive_partial_eq_without_eq,
    40	    reason = "transitively holds serde_json::Value through TaskGraph"
    41	)]
    42	#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
    43	#[serde(deny_unknown_fields)]
    44	pub struct WorkState {
    45	    /// Schema version; always [`VERSION`] for state this tapa writes.
    46	    pub version: u32,
    47	    /// The unified task graph: the structure `analyze` derives from
    48	    /// `tapacc`, plus the post-synthesis annotations `synth` writes in
    49	    /// place.
    50	    pub graph: TaskGraph,
    51	    /// Flow-level settings resolved by the pipeline steps.
    52	    pub flow: FlowSettings,
    53	    /// The floorplan the `floorplan` step computed, when it has run. Its
    54	    /// presence switches codegen and pack into the floorplanned path; absent,
    55	    /// the flow is byte-for-byte as before.
    56	    #[serde(default, skip_serializing_if = "Option::is_none")]
    57	    pub floorplan: Option<FloorplanResult>,
    58	}
    59	
    60	impl WorkState {
    61	    /// Wrap `graph` with the current [`VERSION`] and pre-synth (default)
    62	    /// flow settings.
    63	    #[must_use]
    64	    pub fn new(graph: TaskGraph) -> Self {
    65	        Self {
    66	            version: VERSION,
    67	            graph,
    68	            flow: FlowSettings::default(),
    69	            floorplan: None,
    70	        }
    71	    }
    72	
    73	    /// Parse a state payload with field-path error diagnostics.
    74	    ///
    75	    /// Strict: [`deny_unknown_fields`](WorkState) applies all the way down,
    76	    /// so any key the model does not know is an error rather than something
    77	    /// silently carried along.
    78	    pub fn from_json(json: &str) -> Result<Self, ParseError> {
    79	        let de = &mut serde_json::Deserializer::from_str(json);
    80	        serde_path_to_error::deserialize(de).map_err(|e| ParseError::Schema {
    81	            path: e.path().to_string(),
    82	            message: e.inner().to_string(),
    83	        })
    84	    }
    85	}
    86	
    87	/// Flow-level settings shared across pipeline steps.
    88	///
    89	/// The compilation flow target is deliberately **absent**: [`TaskGraph::target`]
    90	/// is its single home, so there is nothing to reconcile between two copies.
    91	#[derive(Debug, Clone, Default, Serialize, Deserialize, PartialEq, Eq)]
    92	#[serde(deny_unknown_fields)]
    93	pub struct FlowSettings {
    94	    /// Target part number resolved by `synth` from `--part-num` or
    95	    /// `--platform`. `pack` reads it back to build the `.xo`, and `frt-cosim`
    96	    /// reads it out of the packed archive.
    97	    #[serde(default, skip_serializing_if = "Option::is_none")]
    98	    pub part_num: Option<String>,
    99	    /// Vitis platform `synth --platform` ran against, when given. Read by
   100	    /// `pack --bitstream-script` to render the `v++` invocation.
   101	    #[serde(default, skip_serializing_if = "Option::is_none")]
   102	    pub platform: Option<String>,
   103	    /// The **requested** target clock period.
   104	    ///
   105	    /// Distinct from [`crate::Task::clock_period`], which is the per-task
   106	    /// *achieved* estimate HLS reports back: one is an input to synthesis,
   107	    /// the other a result of it. Both are kept.
   108	    #[serde(default, skip_serializing_if = "Option::is_none")]
   109	    pub clock_period: Option<String>,
   110	    /// Set once `synth` has completed for this work dir.
   111	    #[serde(default)]
   112	    pub synthed: bool,
   113	}
   114	
