     1	//! Instance handshake signal generation.
     2	//!
     3	//! Implements: generates state, start,
     4	//! done, idle, ready signals for task instances.
     5	
     6	use tapa_protocol::{HANDSHAKE_DONE, HANDSHAKE_IDLE, HANDSHAKE_READY, HANDSHAKE_START};
     7	use tapa_rtl::builder::{Expr, PortArg};
     8	use tapa_rtl::mutation::{reg, simple_port, wide_reg, wire};
     9	use tapa_rtl::port::Direction;
    10	use tapa_rtl::signal::Signal;
    11	
    12	/// Handshake signals for a single task instance.
    13	pub struct InstanceSignals {
    14	    instance_name: String,
    15	    is_autorun: bool,
    16	}
    17	
    18	impl InstanceSignals {
    19	    /// Create signals for an instance.
    20	    ///
    21	    /// `is_autorun`: true if the instance has a negative step (auto-start).
    22	    ///
    23	    /// # Panics
    24	    ///
    25	    /// Panics if `instance_name` is empty.
    26	    pub fn new(instance_name: impl Into<String>, is_autorun: bool) -> Self {
    27	        let instance_name = instance_name.into();
    28	        assert!(!instance_name.is_empty(), "instance name must not be empty");
    29	        Self {
    30	            instance_name,
    31	            is_autorun,
    32	        }
    33	    }
    34	
    35	    /// Instance state register name: `{instance}__state`.
    36	    pub fn state_name(&self) -> String {
    37	        format!("{}__state", self.instance_name)
    38	    }
    39	
    40	    /// Instance start signal name: `{instance}__ap_start`.
    41	    pub fn start_name(&self) -> String {
    42	        format!("{}__ap_start", self.instance_name)
    43	    }
    44	
    45	    /// Instance done signal name: `{instance}__ap_done`.
    46	    pub fn done_name(&self) -> String {
    47	        format!("{}__ap_done", self.instance_name)
    48	    }
    49	
    50	    /// Instance `is_done` signal name: `{instance}__is_done`.
    51	    pub fn is_done_name(&self) -> String {
    52	        format!("{}__is_done", self.instance_name)
    53	    }
    54	
    55	    /// Instance idle signal name: `{instance}__ap_idle`.
    56	    pub fn idle_name(&self) -> String {
    57	        format!("{}__ap_idle", self.instance_name)
    58	    }
    59	
    60	    /// Instance ready signal name: `{instance}__ap_ready`.
    61	    pub fn ready_name(&self) -> String {
    62	        format!("{}__ap_ready", self.instance_name)
    63	    }
    64	
    65	    /// Expression for the state register.
    66	    pub fn state_expr(&self) -> Expr {
    67	        Expr::ident(self.state_name())
    68	    }
    69	
    70	    /// Expression for the start signal.
    71	    pub fn start_expr(&self) -> Expr {
    72	        Expr::ident(self.start_name())
    73	    }
    74	
    75	    /// Expression for the done signal.
    76	    pub fn done_expr(&self) -> Expr {
    77	        Expr::ident(self.done_name())
    78	    }
    79	
    80	    /// `set_state(new_state)` -> nonblocking assign: `{instance}__state <= new_state`.
    81	    pub fn set_state(&self, new_state: Expr) -> tapa_rtl::builder::Statement {
    82	        tapa_rtl::builder::Statement::NonblockingAssign {
    83	            lhs: self.state_expr(),
    84	            rhs: new_state,
    85	        }
    86	    }
    87	
    88	    /// `is_state(target)` -> equality comparison: `{instance}__state == target`.
    89	    pub fn is_state(&self, target: Expr) -> Expr {
    90	        Expr::eq(self.state_expr(), target)
    91	    }
    92	
    93	    /// Generate all handshake signal declarations for this instance.
    94	    pub fn all_signals(&self) -> Vec<Signal> {
    95	        if self.is_autorun {
    96	            vec![reg(self.start_name())]
    97	        } else {
    98	            vec![
    99	                wide_reg(self.state_name(), "1", "0"),
   100	                wire(self.start_name()),
   101	                wire(self.done_name()),
   102	                wire(self.is_done_name()),
   103	                wire(self.idle_name()),
   104	                wire(self.ready_name()),
   105	            ]
   106	        }
   107	    }
   108	
   109	    /// Generate public handshake port arguments for connecting to the child instance.
   110	    pub fn instance_portargs(&self) -> Vec<PortArg> {
   111	        let mut args = vec![PortArg::new(HANDSHAKE_START, self.start_expr())];
   112	        if !self.is_autorun {
   113	            args.extend([
   114	                PortArg::new(HANDSHAKE_DONE, self.done_expr()),
   115	                PortArg::new(HANDSHAKE_IDLE, Expr::ident(self.idle_name())),
   116	                PortArg::new(HANDSHAKE_READY, Expr::ident(self.ready_name())),
   117	            ]);
   118	        }
   119	        args
   120	    }
   121	
   122	    /// Generate public handshake ports for the FSM module interface.
   123	    pub fn fsm_ports(&self) -> Vec<tapa_rtl::port::Port> {
   124	        if self.is_autorun {
   125	            vec![simple_port(self.start_name(), Direction::Output)]
   126	        } else {
   127	            vec![
   128	                simple_port(self.start_name(), Direction::Output),
   129	                simple_port(self.ready_name(), Direction::Input),
   130	                simple_port(self.done_name(), Direction::Input),
   131	                simple_port(self.idle_name(), Direction::Input),
   132	            ]
   133	        }
   134	    }
   135	}
   136	
   137	#[cfg(test)]
   138	mod tests {
   139	    use super::*;
   140	
   141	    #[test]
   142	    fn non_autorun_signals() {
   143	        let sig = InstanceSignals::new("child_0", false);
   144	        let signals = sig.all_signals();
   145	        assert_eq!(
   146	            signals.len(),
   147	            6,
   148	            "should have state, start, done, is_done, idle, ready"
   149	        );
   150	        assert_eq!(signals[0].name, "child_0__state");
   151	        assert_eq!(signals[1].name, "child_0__ap_start");
