   162	    fn set_state_produces_nonblocking_assign() {
   163	        let sig = InstanceSignals::new("inst", false);
   164	        let stmt = sig.set_state(Expr::int_const(2, 1));
   165	        let text = format!(
   166	            "{}",
   167	            tapa_rtl::builder::AlwaysBlock::posedge("clk", vec![stmt])
   168	        );
   169	        assert!(text.contains("inst__state <= 2'd1"), "got: {text}");
   170	    }
   171	
   172	    #[test]
   173	    fn is_state_produces_equality() {
   174	        let sig = InstanceSignals::new("inst", false);
   175	        let expr = sig.is_state(Expr::int_const(2, 0));
   176	        assert_eq!(expr.to_string(), "(inst__state == 2'd0)");
   177	    }
   178	
   179	    #[test]
   180	    fn instance_portargs_non_autorun() {
   181	        let sig = InstanceSignals::new("child", false);
   182	        let args = sig.instance_portargs();
   183	        assert_eq!(args.len(), 4, "should have start, done, idle, ready");
   184	    }
   185	
   186	    #[test]
   187	    fn instance_portargs_autorun() {
   188	        let sig = InstanceSignals::new("child", true);
   189	        let args = sig.instance_portargs();
   190	        assert_eq!(args.len(), 1, "autorun should only have start");
   191	    }
   192	
   193	    #[test]
   194	    #[should_panic(expected = "instance name must not be empty")]
   195	    fn empty_name_rejected() {
   196	        let _sig = InstanceSignals::new("", false);
   197	    }
   198	
   199	    #[test]
   200	    fn fsm_ports_non_autorun() {
   201	        let sig = InstanceSignals::new("child", false);
   202	        let ports = sig.fsm_ports();
   203	        assert_eq!(ports.len(), 4, "should have start, ready, done, idle");
   204	    }
   205	
   206	    #[test]
   207	    fn fsm_ports_autorun() {
   208	        let sig = InstanceSignals::new("child", true);
   209	        let ports = sig.fsm_ports();
   210	        assert_eq!(ports.len(), 1, "autorun should only have start port");
   211	    }
   212	}
