     1	//! Top-level global FSM for the design root.
     2	//!
     3	//! Generates the 3-state IDLE -> RUNNING -> DONE controller that drives
     4	//! the ap-ctrl handshake and gates on all child `is_done` signals.
     5	
     6	use tapa_protocol::{
     7	    HANDSHAKE_CLK, HANDSHAKE_DONE, HANDSHAKE_IDLE, HANDSHAKE_READY, HANDSHAKE_RST, HANDSHAKE_RST_N,
     8	    HANDSHAKE_START,
     9	};
    10	use tapa_rtl::builder::{AlwaysBlock, CaseItem, ContinuousAssign, Expr, Statement};
    11	use tapa_rtl::mutation::{wide_reg, wire, MutableModule};
    12	
    13	/// FSM state constants for the global program FSM (2-bit).
    14	pub const GLOBAL_STATE_IDLE: &str = "2'b00";
    15	pub const GLOBAL_STATE_RUNNING: &str = "2'b01";
    16	pub const GLOBAL_STATE_DONE: &str = "2'b10";
    17	
    18	/// Generate the global 3-state FSM for a top-level program.
    19	///
    20	/// States: IDLE(00) -> RUNNING(01) -> DONE(10) -> IDLE(00)
    21	/// Transition from RUNNING to DONE is gated by all child `is_done` signals.
    22	///
    23	/// Returns the always block for the FSM, plus continuous assigns for
    24	/// handshake output signals.
    25	pub fn generate_global_fsm(is_done_signal_names: &[String]) -> GlobalFsmOutput {
    26	    let state = Expr::ident("__tapa_state");
    27	
    28	    // Build the RUNNING->DONE transition condition
    29	    let all_done_cond = if is_done_signal_names.is_empty() {
    30	        Expr::lit("1'b1") // No children = always done
    31	    } else {
    32	        is_done_signal_names
    33	            .iter()
    34	            .map(|name| Expr::ident(name.clone()))
    35	            .reduce(Expr::logical_and)
    36	            .unwrap_or_else(|| Expr::lit("1'b1"))
    37	    };
    38	
    39	    // FSM always block
    40	    let fsm_block = AlwaysBlock::posedge(
    41	        HANDSHAKE_CLK,
    42	        vec![Statement::If {
    43	            cond: Expr::ident(HANDSHAKE_RST),
    44	            then_body: vec![Statement::NonblockingAssign {
    45	                lhs: state.clone(),
    46	                rhs: Expr::lit(GLOBAL_STATE_IDLE),
    47	            }],
    48	            else_body: vec![Statement::Case {
    49	                expr: state.clone(),
    50	                items: vec![
    51	                    // IDLE -> RUNNING on start
    52	                    CaseItem::new(
    53	                        Expr::lit(GLOBAL_STATE_IDLE),
    54	                        vec![Statement::If {
    55	                            cond: Expr::ident(HANDSHAKE_START),
    56	                            then_body: vec![Statement::NonblockingAssign {
    57	                                lhs: state.clone(),
    58	                                rhs: Expr::lit(GLOBAL_STATE_RUNNING),
    59	                            }],
    60	                            else_body: vec![],
    61	                        }],
    62	                    ),
    63	                    // RUNNING -> DONE when all children done
    64	                    CaseItem::new(
    65	                        Expr::lit(GLOBAL_STATE_RUNNING),
    66	                        vec![Statement::If {
    67	                            cond: all_done_cond,
    68	                            then_body: vec![Statement::NonblockingAssign {
    69	                                lhs: state.clone(),
    70	                                rhs: Expr::lit(GLOBAL_STATE_DONE),
    71	                            }],
    72	                            else_body: vec![],
    73	                        }],
    74	                    ),
    75	                    // DONE -> IDLE (unconditional)
    76	                    CaseItem::new(
    77	                        Expr::lit(GLOBAL_STATE_DONE),
    78	                        vec![Statement::NonblockingAssign {
    79	                            lhs: state,
    80	                            rhs: Expr::lit(GLOBAL_STATE_IDLE),
    81	                        }],
    82	                    ),
    83	                ],
    84	                default: vec![],
    85	            }],
    86	        }],
    87	    );
    88	
    89	    // Handshake output assigns
    90	    let idle_assign = ContinuousAssign::new(
    91	        Expr::ident(HANDSHAKE_IDLE),
    92	        Expr::eq(Expr::ident("__tapa_state"), Expr::lit(GLOBAL_STATE_IDLE)),
    93	    );
    94	
    95	    GlobalFsmOutput {
    96	        fsm_block,
    97	        idle_assign,
    98	    }
    99	}
   100	
   101	/// Output of global FSM generation.
   102	pub struct GlobalFsmOutput {
   103	    pub fsm_block: AlwaysBlock,
   104	    pub idle_assign: ContinuousAssign,
   105	}
   106	
   107	/// Pipeline signal names for start and done.
   108	pub const START_Q: &str = "__tapa_start_q";
   109	pub const DONE_Q: &str = "__tapa_done_q";
   110	
   111	/// Apply global FSM signals and logic to an FSM module.
   112	///
   113	/// Creates `start_q` and `done_q` pipeline signals:
   114	/// - `start_q[0] = ap_start` (immediate from handshake)
   115	/// - `done_q[0] = (state == STATE_DONE)` (combinational from FSM)
   116	/// - `ap_idle = (state == STATE_IDLE)`
   117	/// - `ap_done = done_q` (pipelined output)
   118	/// - `ap_ready = done_q` (immediate completion signal)
   119	///
   120	/// Children use `start_q` for IDLE->RUNNING and `done_q` for DONE->IDLE.
   121	pub fn apply_global_fsm(fsm_module: &mut MutableModule, is_done_signal_names: &[String]) {
   122	    // Add top-level handshake ports to FSM module interface
   123	    let _ = fsm_module.add_port(tapa_rtl::mutation::simple_port(
   124	        HANDSHAKE_START,
   125	        tapa_rtl::port::Direction::Input,
   126	    ));
   127	    let _ = fsm_module.add_port(tapa_rtl::mutation::simple_port(
   128	        HANDSHAKE_DONE,
   129	        tapa_rtl::port::Direction::Output,
   130	    ));
   131	    let _ = fsm_module.add_port(tapa_rtl::mutation::simple_port(
   132	        HANDSHAKE_IDLE,
   133	        tapa_rtl::port::Direction::Output,
   134	    ));
   135	    let _ = fsm_module.add_port(tapa_rtl::mutation::simple_port(
   136	        HANDSHAKE_READY,
   137	        tapa_rtl::port::Direction::Output,
   138	    ));
   139	
   140	    // Add state register
   141	    let _ = fsm_module.add_signal(wide_reg("__tapa_state", "1", "0"));
   142	
   143	    // Add reset wire
   144	    let _ = fsm_module.add_signal(wire(HANDSHAKE_RST));
   145	
   146	    // Add pipeline signals
   147	    let _ = fsm_module.add_signal(wire(START_Q));
   148	    let _ = fsm_module.add_signal(wire(DONE_Q));
   149	
   150	    // assign ap_rst = ~ap_rst_n
   151	    fsm_module.add_assign(ContinuousAssign::new(
   152	        Expr::ident(HANDSHAKE_RST),
   153	        Expr::logical_not(Expr::ident(HANDSHAKE_RST_N)),
   154	    ));
   155	
   156	    // start_q = ap_start (pipeline stage 0 = raw input)
   157	    fsm_module.add_assign(ContinuousAssign::new(
   158	        Expr::ident(START_Q),
   159	        Expr::ident(HANDSHAKE_START),
   160	    ));
   161	
   162	    // Generate and apply FSM
   163	    let output = generate_global_fsm(is_done_signal_names);
   164	    fsm_module.add_always(output.fsm_block);
   165	    fsm_module.add_assign(output.idle_assign);
   166	
   167	    // done_q = (state == STATE_DONE) — combinational from FSM
   168	    fsm_module.add_assign(ContinuousAssign::new(
   169	        Expr::ident(DONE_Q),
   170	        Expr::eq(Expr::ident("__tapa_state"), Expr::lit(GLOBAL_STATE_DONE)),
   171	    ));
   172	
   173	    // ap_done driven from done_q (pipelined output)
   174	    fsm_module.add_assign(ContinuousAssign::new(
   175	        Expr::ident(HANDSHAKE_DONE),
   176	        Expr::ident(DONE_Q),
   177	    ));
   178	    // ap_ready driven from done_q (immediate)
   179	    fsm_module.add_assign(ContinuousAssign::new(
   180	        Expr::ident(HANDSHAKE_READY),
   181	        Expr::ident(DONE_Q),
   182	    ));
   183	}
   184	
   185	#[cfg(test)]
   186	mod tests {
   187	    use super::*;
   188	    use tapa_rtl::VerilogModule;
   189	
   190	    #[test]
   191	    fn global_fsm_has_three_states() {
   192	        let output = generate_global_fsm(&["child_0__is_done".into()]);
   193	        let text = output.fsm_block.to_string();
   194	        assert!(text.contains(GLOBAL_STATE_IDLE), "got:\n{text}");
   195	        assert!(text.contains(GLOBAL_STATE_RUNNING), "got:\n{text}");
   196	        assert!(text.contains(GLOBAL_STATE_DONE), "got:\n{text}");
   197	    }
   198	
   199	    #[test]
   200	    fn global_fsm_gates_on_is_done() {
   201	        let output = generate_global_fsm(&["child_a__is_done".into(), "child_b__is_done".into()]);
   202	        let text = output.fsm_block.to_string();
   203	        assert!(text.contains("child_a__is_done"), "got:\n{text}");
