   216	    fn apply_global_fsm_to_module() {
   217	        let source = "module top_fsm (\n  input wire ap_clk,\n  input wire ap_rst_n\n);\nendmodule";
   218	        let module = VerilogModule::parse(source).unwrap();
   219	        let mut mm = MutableModule::from_parsed(module);
   220	        apply_global_fsm(&mut mm, &["child__is_done".into()]);
   221	        let emitted = mm.emit();
   222	        assert!(emitted.contains("__tapa_state"), "got:\n{emitted}");
   223	        assert!(emitted.contains("ap_idle"), "got:\n{emitted}");
   224	        assert!(
   225	            emitted.contains("always @(posedge ap_clk)"),
   226	            "got:\n{emitted}"
   227	        );
   228	        // Pipeline signals
   229	        assert!(
   230	            emitted.contains(START_Q),
