     1	//! Instance handshake signal generation.
     2	//!
     3	//! Implements: generates state, start,
     4	//! done, idle, ready signals for task instances.
     5	
     6	use tapa_protocol::{HANDSHAKE_DONE, HANDSHAKE_IDLE, HANDSHAKE_READY, HANDSHAKE_START};
     7	use tapa_rtl::builder::{Expr, PortArg};
     8	use tapa_rtl::mutation::{reg, simple_port, wide_reg, wire};
     9	use tapa_rtl::port::Direction;
    10	use tapa_rtl::signal::Signal;
