239	void XilinxBackend::RewriteSignature(const TaskModel& task, bool is_top,
240	                                     clang::Rewriter& rewriter) const {
241	  const Lvl lvl = LvlOf(task.level, is_top, is_vitis_);
242	  if (lvl == Lvl::kLower) return;  // lower-level signatures are unchanged
243	
244	  // Middle/top: replace mmap parameters with 64-bit base addresses, on every
245	  // declaration of the function (the forward declaration and the definition),
246	  // so the emitted signatures agree.
247	  bool rewrote_axis_stream = false;
248	  for (const clang::FunctionDecl* decl : task.def->redecls()) {
249	    for (const clang::ParmVarDecl* param : decl->parameters()) {
250	      const std::string name = param->getNameAsString();
251	      const TapaKind kind = ClassifyTapaType(param);
252	      if (kind == TapaKind::kMmap || kind == TapaKind::kAsyncMmap) {
253	        rewriter.ReplaceText(
254	            param->getTypeSourceInfo()->getTypeLoc().getSourceRange(),
255	            "uint64_t");
256	        rewriter.ReplaceText(param->getLocation(), OffsetName(name));
257	      } else if (IsMmapArray(kind)) {
258	        std::string text;
259	        for (int64_t i = 0; i < ArraySize(param); ++i) {
260	          if (!text.empty()) text += ", ";
261	          text += "uint64_t " + ArrayElemOffset(name, static_cast<int>(i));
262	        }
263	        rewriter.ReplaceText(param->getSourceRange(), text);
264	      } else if (lvl == Lvl::kTop &&
265	                 (kind == TapaKind::kIStream || kind == TapaKind::kOStream)) {
266	        // Vitis top-level streams become axis interfaces. Rewrite the type to
267	        // hls::stream<qdma_axis<W>> so Vitis HLS emits `{name}_TDATA/_TVALID/
268	        // _TREADY/_TLAST` (what the cosim testbench binds to), instead of the
269	        // `tapa::istream` disaggregated `_s_*` member ports. Mirrors the legacy
270	        // rewriter's RewriteTopLevelFuncArguments.
271	        if (const auto* arg = GetTemplateArg(param->getType(), 0)) {
272	          if (arg->getKind() == clang::TemplateArgument::Type) {
273	            const uint32_t w =
274	                param->getASTContext().getTypeInfo(arg->getAsType()).Width;
275	            rewriter.ReplaceText(
276	                param->getTypeSourceInfo()->getTypeLoc().getSourceRange(),
277	                "hls::stream<qdma_axis<" + std::to_string(w) + ", 0, 0, 0> >&");
278	            rewrote_axis_stream = true;
279	          }
280	        }
281	      }
282	    }
283	  }
284	
285	  // The rewritten signature (and the dummy writes in the top task's body) spell
286	  // qdma_axis<...>, whose definition lives in ap_axi_sdata.h. This runs once
287	  // per emitted cpp (RewriteSignature is called for the top task in every
288	  // file), so every file that carries the rewritten decl gets the header.
289	  if (rewrote_axis_stream) {
290	    rewriter.InsertText(task.def->getBeginLoc(),
291	                        "#include \"ap_axi_sdata.h\"\n"
292	                        "#include \"hls_stream.h\"\n\n",
293	                        /*InsertAfter=*/true);
294	  }
295	}
