297	void XilinxBackend::RewriteTaskFunc(const TaskModel& task, bool is_top,
298	                                    clang::Rewriter& rewriter) const {
299	  const clang::FunctionDecl* func = task.def;
300	  if (!func->hasBody()) return;
301	  const Lvl lvl = LvlOf(task.level, is_top, is_vitis_);
302	  const std::string lines = GeneratePreamble(*this, task, is_top);
303	
304	  if (lvl == Lvl::kLower) {
305	    // Leading newline so the first pragma starts its own line after the brace.
306	    rewriter.InsertTextAfterToken(func->getBody()->getBeginLoc(), "\n" + lines);
307	    RewriteStreamDefinitions(func, rewriter);
308	    RemoveInline(func, rewriter);
309	    return;
310	  }
311	
312	  // Middle level (and top level in non-Vitis mode): replace the body with a
313	  // shell carrying just the interface pragmas.
314	  if (lvl == Lvl::kMiddle || (lvl == Lvl::kTop && !is_vitis_)) {
315	    rewriter.ReplaceText(func->getBody()->getSourceRange(),
316	                         "{\n" + lines + "}\n");
317	    RemoveInline(func, rewriter);
318	    return;
319	  }
320	
321	  // Top level in Vitis mode: the shell carries an s_axilite return-control
322	  // pragma, and every declaration (forward decl + definition) is wrapped in
323	  // extern "C" (Vitis only links extern-C kernels).
324	  const std::string shell =
325	      "{\n" + lines +
326	      "#pragma HLS interface s_axilite port = return bundle = control\n}\n";
327	  for (const clang::FunctionDecl* decl : func->redecls()) {
328	    clang::SourceLocation end = decl->getEndLoc();
329	    if (decl->isThisDeclarationADefinition()) {
330	      rewriter.ReplaceText(decl->getBody()->getSourceRange(), shell);
331	    } else {
332	      // Insert after the declaration's trailing semicolon.
333	      const clang::SourceLocation after = clang::Lexer::findLocationAfterToken(
334	          end, clang::tok::semi, rewriter.getSourceMgr(),
335	          rewriter.getLangOpts(), /*SkipTrailingWhitespaceAndNewLine=*/true);
336	      if (after.isValid()) end = after;
337	    }
338	    rewriter.InsertText(decl->getBeginLoc(), "extern \"C\" {\n\n");
339	    rewriter.InsertTextAfterToken(end, "\n\n}  // extern \"C\"\n");
340	    RemoveInline(decl, rewriter);

