  1	// tapacc: the TAPA C-to-HLS rewriter. Parses a (flattened) TAPA C++ translation
  2	// unit into a typed program model (frontend/), generates per-task vendor HLS
  3	// via a backend (codegen/), and emits on stdout the task graph the tapa-ir
  4	// crate consumes: {top, target, tasks:{name:{code, level, synth,
  5	// readable_name, ports, tasks, fifos}}}. `tapa analyze` nests that payload
  6	// under the "graph" key of the work dir's tapa.json.
  7	//
  8	// Two distinct notions of "target" live in that schema, and the tapa-ir crate
  9	// parses both as closed enums with deny_unknown_fields:
 10	//   - root "target": the vendor FLOW, kebab-case "xilinx-vitis"/"xilinx-hls".
 11	//   - per-task "synth": the synthesis POLICY, "hls"/"ignore" only -- it answers
 12	//     just "synthesize or skip". The internal three-valued SynthTarget still
 13	//     carries the flow per task so the right backend gets picked, but that
 14	//     distinction collapses on the wire.
 15	//
 16	// Changing what this file emits changes a contract with Rust code that cannot
 17	// see it. `bazel test //tapa-core:tapacc_conformance_test` (Linux only) is the
 18	// guard: it runs this binary on tests/apps/vadd/vadd.cpp and strict-parses the
 19	// stdout below with tapa-ir's real types, so a field tapa-ir does not model --
 20	// or a required one that stops being emitted -- fails there rather than in
 21	// someone's build.
 22	
 23	#include <iostream>
 24	#include <memory>
 25	
 26	#include "clang/AST/ASTConsumer.h"
 27	#include "clang/AST/ASTContext.h"
 28	#include "clang/Frontend/CompilerInstance.h"
 29	#include "clang/Frontend/FrontendActions.h"
 30	#include "clang/Tooling/CommonOptionsParser.h"
 31	#include "clang/Tooling/Tooling.h"
 32	#include "llvm/Support/CommandLine.h"
 33	#include "llvm/Support/raw_ostream.h"
 34	
 35	#include "nlohmann/json.hpp"
 36	
 37	#include "codegen/ignore.h"
 38	#include "codegen/rewrite.h"
 39	#include "codegen/schema_fields.h"
 40	#include "codegen/xilinx.h"
 41	#include "frontend/build_program.h"
 42	#include "frontend/classify.h"
 43	#include "frontend/program.h"
 44	
 45	namespace {
 46	
 47	using namespace tapa::cc;
 48	
 49	const char* LevelStr(TaskLevel level) {
 50	  return level == TaskLevel::kUpper ? "upper" : "lower";
 51	}
 52	
 53	// Maps the per-task synthesis policy to its wire string. tapa-ir's SynthTarget
 54	// is closed over {"hls", "ignore"}, so both HLS and Vitis tasks collapse to
 55	// "hls": the per-task field only says whether to synthesize. The flow itself is
 56	// emitted once at the graph root (see FlowStr).
 57	const char* SynthStr(SynthTarget target) {
 58	  switch (target) {
 59	    case SynthTarget::kIgnore:
 60	      return "ignore";
 61	    case SynthTarget::kXilinxHls:
 62	    case SynthTarget::kXilinxVitis:
 63	      return "hls";
 64	  }
 65	  // Unreachable for a valid enumerator; keeps -Wswitch (not -Wswitch-default)
 66	  // free to flag a future enumerator that needs a policy decision here.
 67	  return "hls";
 68	}
 69	
 70	// Wire string for the root-level vendor flow. Kebab-case, unlike the per-task
 71	// policy above.
 72	const char* FlowStr(bool is_vitis) {
 73	  return is_vitis ? "xilinx-vitis" : "xilinx-hls";
 74	}
 75	
 76	nlohmann::json PortJson(const Port& port) {
 77	  nlohmann::json j{{kFieldCat, TapaKindCat(port.kind)},
 78	                   {kFieldName, port.name},
 79	                   {kFieldType, port.ctype},
 80	                   {kFieldWidth, port.width}};
 81	  if (port.chan_count) j[kFieldChanCount] = *port.chan_count;
 82	  if (port.chan_size) j[kFieldChanSize] = *port.chan_size;
 83	  return j;
 84	}
 85	
 86	nlohmann::json InstanceJson(const Instance& inst) {
 87	  nlohmann::json j;
 88	  j[kFieldStep] = inst.step;
 89	  if (inst.name) j[kFieldName] = *inst.name;
 90	  j[kFieldArgs] = nlohmann::json::object();
 91	  for (const auto& [port, arg] : inst.args) {
 92	    j[kFieldArgs][port] = {{kFieldArg, arg.arg},
 93	                           {kFieldCat, TapaKindCat(arg.cat)}};
 94	  }
 95	  return j;
 96	}
 97	
 98	nlohmann::json StreamJson(const StreamDecl& stream) {
 99	  nlohmann::json j;
100	  // External top-level stream ports have no depth; the key is omitted so
101	  // tapa-ir parses the entry as an external (kernel-boundary) FIFO.
102	  if (stream.depth) j[kFieldDepth] = *stream.depth;
103	  if (stream.produced_by) {
104	    j[kFieldProducedBy] = {stream.produced_by->task, stream.produced_by->index};
105	  }
106	  if (stream.consumed_by) {
107	    j[kFieldConsumedBy] = {stream.consumed_by->task, stream.consumed_by->index};
108	  }
109	  return j;
110	}
111	
112	llvm::cl::OptionCategory g_category("tapacc-ng options");
113	
114	llvm::cl::opt<std::string> g_top("top", llvm::cl::Required,
115	                                 llvm::cl::desc("Top-level task name"),
116	                                 llvm::cl::cat(g_category));
117	
118	enum class CliTarget { kHls, kVitis };
119	llvm::cl::opt<CliTarget> g_target(
120	    "target", llvm::cl::desc("Target flow (default xilinx-hls)"),
121	    llvm::cl::init(CliTarget::kHls), llvm::cl::cat(g_category),
122	    llvm::cl::values(
123	        clEnumValN(CliTarget::kHls, "xilinx-hls", "Xilinx HLS (default)"),
124	        clEnumValN(CliTarget::kVitis, "xilinx-vitis", "Xilinx Vitis")));
125	
126	class NgConsumer : public clang::ASTConsumer {
127	 public:
128	  void HandleTranslationUnit(clang::ASTContext& ctx) override {
129	    using namespace tapa::cc;
130	    const bool is_vitis = g_target == CliTarget::kVitis;
131	    const SynthTarget default_target =
132	        is_vitis ? SynthTarget::kXilinxVitis : SynthTarget::kXilinxHls;
133	
134	    Program program = BuildProgram(ctx, g_top, default_target);
135	    const XilinxBackend hls(/*is_vitis=*/false);
136	    const XilinxBackend vitis(/*is_vitis=*/true);
137	    const IgnoreBackend ignore;
138	
139	    nlohmann::json out;
140	    out[kFieldTop] = program.top;
141	    out[kFieldTarget] = FlowStr(is_vitis);
142	    out[kFieldTasks] = nlohmann::json::object();
143	    for (const auto& [name, task] : program.tasks) {
144	      const Backend* backend = &hls;
145	      if (task.target == SynthTarget::kXilinxVitis) backend = &vitis;
146	      if (task.target == SynthTarget::kIgnore) backend = &ignore;
147	
148	      nlohmann::json& t = out[kFieldTasks][name];
149	      t[kFieldCode] = EmitTaskCode(program, task, *backend, ctx);
150	      t[kFieldLevel] = LevelStr(task.level);
151	      t[kFieldSynth] = SynthStr(task.target);
152	      t[kFieldReadableName] = task.readable_name;
153	      t[kFieldPorts] = nlohmann::json::array();
154	      for (const Port& port : task.ports)
155	        t[kFieldPorts].push_back(PortJson(port));
156	      if (task.level == TaskLevel::kUpper) {
157	        t[kFieldTasks] = nlohmann::json::object();
158	        for (const auto& [child, insts] : task.instances) {
159	          nlohmann::json arr = nlohmann::json::array();
160	          for (const Instance& inst : insts) arr.push_back(InstanceJson(inst));
161	          t[kFieldTasks][child] = std::move(arr);
162	        }
163	        t[kFieldFifos] = nlohmann::json::object();
164	        for (const auto& [fifo, stream] : task.streams) {
165	          t[kFieldFifos][fifo] = StreamJson(stream);
166	        }
167	      }
168	    }
169	    std::cout << out;
170	  }
171	};
172	
173	class NgAction : public clang::ASTFrontendAction {
174	 public:
175	  std::unique_ptr<clang::ASTConsumer> CreateASTConsumer(
176	      clang::CompilerInstance&, llvm::StringRef) override {
177	    return std::make_unique<NgConsumer>();
178	  }
179	};
180	
181	}  // namespace
182	
183	int main(int argc, const char** argv) {
184	  auto parser =
185	      clang::tooling::CommonOptionsParser::create(argc, argv, g_category);
186	  if (!parser) {
187	    llvm::errs() << llvm::toString(parser.takeError()) << "\n";
188	    return 1;
189	  }
190	  clang::tooling::ClangTool tool(parser->getCompilations(),
191	                                 parser->getSourcePathList());
192	  return tool.run(clang::tooling::newFrontendActionFactory<NgAction>().get());
193	}

