    23	    let mut ports = vec![
    24	        PortArg::new("ACLK", Expr::ident(HANDSHAKE_CLK)),
    25	        PortArg::new("ARESET", Expr::ident(HANDSHAKE_RST)),
    26	        PortArg::new("ACLK_EN", Expr::lit("1'b1")),
    27	    ];
    28	    for &axi_port in S_AXI_LITE_CTRL_PORTS {
    29	        ports.push(PortArg::new(
    30	            axi_port,
    31	            Expr::ident(format!("{S_AXI_NAME}_{axi_port}")),
    32	        ));
    33	    }
    34	    for &sig in &[
    35	        HANDSHAKE_START,
    36	        HANDSHAKE_DONE,
    37	        HANDSHAKE_IDLE,
    38	        HANDSHAKE_READY,
    39	        "interrupt",
