    43	
    44	    for port in &task.ports {
    45	        let sanitized = tapa_rtl::module::sanitize_array_name(&port.name);
    46	        let ctrl_port_names = if port.cat.is_scalar() {
    47	            let width = port.width.max(1);
    48	            if width == 1 {
    49	                let _ = mm.add_signal(wire(&sanitized));
    50	            } else {
    51	                let _ = mm.add_signal(wide_wire(&sanitized, &(width - 1).to_string(), "0"));
    52	            }
    53	            vec![sanitized]
    54	        } else if port.cat.is_mmap_like() {
    55	            if let Some(chan_count) = port.chan_count {
    56	                (0..chan_count)
    57	                    .map(|idx| {
    58	                        let name = format!("{sanitized}_{idx}_offset");
    59	                        let _ = mm.add_signal(wide_wire(&name, "63", "0"));
    60	                        name
    61	                    })
    62	                    .collect()
    63	            } else {
    64	                let name = format!("{sanitized}_offset");
    65	                let _ = mm.add_signal(wide_wire(&name, "63", "0"));
    66	                vec![name]
    67	            }
    68	        } else {
    69	            // Streams contribute no s_axilite control ports.
    70	            Vec::new()
    71	        };
    72	        for ctrl_port_name in ctrl_port_names {
    73	            ports.push(PortArg::new(
    74	                ctrl_port_name.clone(),
    75	                Expr::ident(ctrl_port_name),
    76	            ));
    77	        }
    78	    }
    79	
    80	    let inst = tapa_rtl::builder::ModuleInstance::new(
    81	        format!("{task_name}_control_s_axi"),
    82	        "control_s_axi_U",
    83	    )
    84	    .with_params(vec![
    85	        ParamArg::new(
    86	            "C_S_AXI_ADDR_WIDTH",
    87	            Expr::ident("C_S_AXI_CONTROL_ADDR_WIDTH"),
    88	        ),
    89	        ParamArg::new(
    90	            "C_S_AXI_DATA_WIDTH",
    91	            Expr::ident("C_S_AXI_CONTROL_DATA_WIDTH"),
    92	        ),
    93	    ])
    94	    .with_ports(ports);
    95	    mm.add_instance(inst);
    96	}
