     8	namespace tapa::cc {
     9	
    10	namespace {
    11	
    12	TapaKind ClassifyByQualifiedName(std::string_view name) {
    13	  // Keys are the qualified record names Clang prints for the TAPA class
    14	  // templates (without template arguments), matched exactly.
    15	  static const std::unordered_map<std::string_view, TapaKind> kTable = {
    16	      {"tapa::istream", TapaKind::kIStream},
    17	      {"tapa::ostream", TapaKind::kOStream},
    18	      {"tapa::istreams", TapaKind::kIStreams},
    19	      {"tapa::ostreams", TapaKind::kOStreams},
    20	      {"tapa::stream", TapaKind::kStream},
    21	      {"tapa::streams", TapaKind::kStreams},
    22	      {"tapa::mmap", TapaKind::kMmap},
    23	      {"tapa::mmaps", TapaKind::kMmaps},
    24	      {"tapa::async_mmap", TapaKind::kAsyncMmap},
    25	      {"tapa::immap", TapaKind::kImmap},
    26	      {"tapa::ommap", TapaKind::kOmmap},
    27	      {"tapa::hmap", TapaKind::kHmap},
    28	      {"tapa::task", TapaKind::kTask},
    29	      {"tapa::seq", TapaKind::kSeq},
    30	      {"tapa::executable", TapaKind::kExecutable},
    31	  };
    32	  const auto it = kTable.find(name);
    33	  return it == kTable.end() ? TapaKind::kNotTapa : it->second;
    34	}
    35	
    36	}  // namespace
    37	
    38	TapaKind ClassifyTapaType(clang::QualType type) {
    39	  // Peel lvalue-references and template-parameter substitutions so that
    40	  // `tapa::mmap<T>&`, `const tapa::mmap<T>&`, and a substituted `T` all reduce
    41	  // to the underlying record.
    42	  for (;;) {
    43	    if (const auto* ref = type->getAs<clang::LValueReferenceType>()) {
    44	      type = ref->getPointeeType();
    45	      continue;
    46	    }
    47	    if (const auto* subst = type->getAs<clang::SubstTemplateTypeParmType>()) {
    48	      type = subst->getReplacementType();
    49	      continue;
    50	    }
    51	    break;
    52	  }
    53	  if (const clang::RecordDecl* record = type->getAsRecordDecl()) {
    54	    return ClassifyByQualifiedName(record->getQualifiedNameAsString());
    55	  }
    56	  // A dependent specialization (e.g. `tapa::mmap<mmap_type>` inside a template)
    57	  // has no record decl; classify by the template name instead. A bare template
    58	  // parameter type (e.g. `tapa_mmap_type`) has neither and stays kNotTapa.
    59	  if (const auto* spec = type->getAs<clang::TemplateSpecializationType>()) {
    60	    if (const clang::TemplateDecl* decl =
    61	            spec->getTemplateName().getAsTemplateDecl()) {
    62	      return ClassifyByQualifiedName(decl->getQualifiedNameAsString());
    63	    }
    64	  }
    65	  return TapaKind::kNotTapa;
    66	}
    67	
    68	const char* TapaKindCat(TapaKind k) {
    69	  switch (k) {
    70	    case TapaKind::kIStream:
    71	      return "istream";
    72	    case TapaKind::kOStream:
    73	      return "ostream";
    74	    case TapaKind::kIStreams:
    75	      return "istreams";
    76	    case TapaKind::kOStreams:
    77	      return "ostreams";
    78	    case TapaKind::kMmap:
    79	    case TapaKind::kMmaps:
    80	      return "mmap";
    81	    case TapaKind::kAsyncMmap:
    82	      return "async_mmap";
    83	    case TapaKind::kImmap:
    84	      return "immap";
    85	    case TapaKind::kOmmap:
    86	      return "ommap";
    87	    case TapaKind::kHmap:
    88	      return "hmap";
    89	    default:
    90	      return "scalar";
    91	  }
    92	}
    93	
    94	}  // namespace tapa::cc

