  1	//! Compilation flow target.
  2	
  3	use std::str::FromStr;
  4	
  5	use serde::{Deserialize, Serialize};
  6	use strum::EnumString;
  7	
  8	/// Compilation flow target — the two flows the pipeline can drive.
  9	///
 10	/// Serializes to the exact wire strings `"xilinx-vitis"` / `"xilinx-hls"`.
 11	/// [`crate::TaskGraph::target`] is its single home — it is deliberately not
 12	/// duplicated into the flow settings block alongside it.
 13	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, EnumString)]
 14	#[strum(serialize_all = "kebab-case")]
 15	pub enum Target {
 16	    XilinxVitis,
 17	    XilinxHls,
 18	}
 19	
 20	impl Target {
 21	    /// Canonical wire string (`"xilinx-vitis"` / `"xilinx-hls"`).
 22	    #[must_use]
 23	    pub const fn as_str(self) -> &'static str {
 24	        match self {
 25	            Self::XilinxVitis => "xilinx-vitis",
 26	            Self::XilinxHls => "xilinx-hls",
 27	        }
 28	    }
 29	}
 30	
 31	impl Serialize for Target {
 32	    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
 33	        serializer.serialize_str(self.as_str())
 34	    }
 35	}
 36	
 37	impl<'de> Deserialize<'de> for Target {
 38	    fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
 39	        let s = String::deserialize(deserializer)?;
 40	        Self::from_str(&s).map_err(|_| {
 41	            // The flow target has exactly one home (`TaskGraph::target`), so
 42	            // this parse is the only place an unsupported flow can be caught
 43	            // — it owes the user the list of flows that do work.
 44	            serde::de::Error::custom(format!(
 45	                "unsupported target `{s}`; \
 46	                 supported flows are `xilinx-vitis` and `xilinx-hls`"
 47	            ))
 48	        })
 49	    }
 50	}
 51	
 52	#[cfg(test)]
 53	mod tests {
 54	    use super::*;
 55	
 56	    #[test]
 57	    fn xilinx_vitis_round_trips() {
 58	        let json = serde_json::to_string(&Target::XilinxVitis).expect("serialize");
 59	        assert_eq!(json, r#""xilinx-vitis""#);
 60	        let back: Target = serde_json::from_str(&json).expect("deserialize");
 61	        assert_eq!(back, Target::XilinxVitis);
 62	    }
 63	
 64	    #[test]
 65	    fn xilinx_hls_round_trips() {
 66	        let json = serde_json::to_string(&Target::XilinxHls).expect("serialize");
 67	        assert_eq!(json, r#""xilinx-hls""#);
 68	        let back: Target = serde_json::from_str(&json).expect("deserialize");
 69	        assert_eq!(back, Target::XilinxHls);
 70	    }
 71	
 72	    #[test]
 73	    fn as_str_matches_wire_form() {
 74	        assert_eq!(Target::XilinxVitis.as_str(), "xilinx-vitis");
 75	        assert_eq!(Target::XilinxHls.as_str(), "xilinx-hls");
 76	    }
 77	
 78	    #[test]
 79	    fn from_str_parses_wire_form() {
 80	        assert_eq!(
 81	            Target::from_str("xilinx-vitis").expect("parse"),
 82	            Target::XilinxVitis,
 83	        );
 84	        assert_eq!(
 85	            Target::from_str("xilinx-hls").expect("parse"),
 86	            Target::XilinxHls,
 87	        );
 88	    }
 89	
 90	    #[test]
 91	    fn unknown_value_rejected() {
 92	        assert!(
 93	            serde_json::from_str::<Target>(r#""cpu-sim""#).is_err(),
 94	            "unknown target must be rejected",
 95	        );
 96	        assert!(
 97	            Target::from_str("cpu-sim").is_err(),
 98	            "unknown target must be rejected by FromStr",
 99	        );
100	    }
101	}

