    11	// Peel lvalue-references and template-parameter substitutions so that
    12	// `tapa::mmap<T>&` and a substituted `T` both expose their arguments.
    13	clang::QualType Peel(clang::QualType type) {
    14	  for (bool changed = true; changed;) {
    15	    changed = false;
    16	    if (const auto* ref = type->getAs<clang::LValueReferenceType>()) {
    17	      type = ref->getPointeeType();
    18	      changed = true;
    19	    }
    20	    if (const auto* subst = type->getAs<clang::SubstTemplateTypeParmType>()) {
    21	      type = subst->getReplacementType();
    22	      changed = true;
    23	    }
    24	  }
    25	  return type;
    26	}
    27	
    28	}  // namespace
    29	
    30	const clang::TemplateArgument* GetTemplateArg(clang::QualType type,
    31	                                              unsigned idx) {
    32	  type = Peel(type);
    33	
    34	  // Prefer the as-written specialization type so type arguments keep their
    35	  // source spelling (e.g. a typedef stays a typedef).
    36	  if (const auto* spec = type->getAs<clang::TemplateSpecializationType>()) {
    37	    const auto args = spec->template_arguments();
    38	    if (idx < args.size()) return &args[idx];
    39	  }
    40	  if (const auto* record = type->getAs<clang::RecordType>()) {
    41	    if (const auto* decl =
    42	            llvm::dyn_cast<clang::ClassTemplateSpecializationDecl>(
    43	                record->getDecl())) {
    44	      const auto& args = decl->getTemplateArgs();
    45	      if (idx < args.size()) return &args[idx];
    46	    }
    47	  }
    48	  return nullptr;
    49	}
    50	
    51	std::optional<int64_t> IntTemplateArg(clang::QualType type, unsigned idx) {
    52	  // Resolve via the canonical class-template specialization: unlike the
    53	  // as-written `TemplateSpecializationType`, its arguments have non-type
    54	  // parameters already evaluated to `Integral` (the as-written form stores
    55	  // them as unevaluated `Expression`s).
    56	  type = Peel(type);
    57	  const auto* record = type->getAs<clang::RecordType>();
    58	  if (record == nullptr) return std::nullopt;
    59	  const auto* spec =
    60	      llvm::dyn_cast<clang::ClassTemplateSpecializationDecl>(record->getDecl());
    61	  if (spec == nullptr) return std::nullopt;
    62	  const auto& args = spec->getTemplateArgs();
    63	  if (idx >= args.size()) return std::nullopt;
    64	  return TemplateArgAsInt(args[idx]);
    65	}
