 28	// Bit width of the element (0th template arg) type, or 0 if absent.
 29	uint32_t ElementWidth(const clang::ASTContext& ctx,
 30	                      const clang::ParmVarDecl* param) {
 31	  if (const auto* arg = GetTemplateArg(param->getType(), 0)) {
 32	    if (arg->getKind() == clang::TemplateArgument::Type) {
 33	      return BitWidth(ctx, arg->getAsType());
 34	    }
 35	  }
 36	  return 0;
 37	}
