 49	std::vector<Port> BuildPorts(const clang::ASTContext& ctx,
 50	                             const clang::FunctionDecl* task) {
 51	  std::vector<Port> ports;
 52	  for (const clang::ParmVarDecl* param : task->parameters()) {
 53	    const TapaKind kind = ClassifyTapaType(param);
 54	    const std::string name = param->getNameAsString();
 55	    const std::string elem = ElementTypeName(param);
 56	    const uint32_t elem_width = ElementWidth(ctx, param);
 57	
 58	    switch (kind) {
 59	      case TapaKind::kMmap:
 60	      case TapaKind::kImmap:
 61	      case TapaKind::kOmmap:
 62	      case TapaKind::kAsyncMmap:
 63	        ports.push_back(Port{name, kind, elem + "*", elem_width, std::nullopt,
 64	                             std::nullopt});
 65	        break;
 66	
 67	      case TapaKind::kMmaps: {
 68	        // Expand to one `mmap` port per channel (name[i]).
 69	        const uint32_t n = IntArg(param, 1).value_or(0);
 70	        for (uint32_t i = 0; i < n; ++i) {
 71	          ports.push_back(Port{ArrayElemName(name, i), TapaKind::kMmap,
 72	                               elem + "*", elem_width, std::nullopt,
 73	                               std::nullopt});
 74	        }
 75	        break;
 76	      }
 77	
 78	      case TapaKind::kHmap:
 79	        ports.push_back(Port{name, kind, elem + "*", elem_width,
 80	                             IntArg(param, 1), IntArg(param, 2)});
 81	        break;
 82	
 83	      case TapaKind::kIStream:
 84	      case TapaKind::kOStream:
 85	        ports.push_back(
 86	            Port{name, kind, elem, elem_width, std::nullopt, std::nullopt});
 87	        break;
 88	
 89	      case TapaKind::kIStreams:
 90	      case TapaKind::kOStreams:
 91	        ports.push_back(
 92	            Port{name, kind, elem, elem_width, IntArg(param, 1), std::nullopt});
 93	        break;
 94	
 95	      default:
 96	        // Scalar: the parameter's own type and width.
 97	        ports.push_back(
 98	            Port{name, TapaKind::kNotTapa, param->getType().getAsString(),
 99	                 BitWidth(ctx, param->getType()), std::nullopt, std::nullopt});
100	        break;
101	    }
102	  }
103	  return ports;
104	}
