35:pub struct Task {
//! Task definition types.

use std::collections::BTreeMap;

use indexmap::IndexMap;
use serde::{Deserialize, Serialize};
use serde_json::Value;

use crate::instance::TaskInstance;
use crate::interconnect::InterconnectDefinition;
use crate::port::Port;
use crate::synth_target::SynthTarget;

/// Level of a task in the hierarchy.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum TaskLevel {
    Lower,
    Upper,
}

/// A single task in the unified task graph.
///
/// The tapacc output and the post-synthesis design share this one type:
/// analyze emits the structural fields, synth populates the post-synthesis
/// annotation block (`clock_period`, `self_area`, `total_area`) in place,
/// and report reads them back. The annotations are absent in tapacc output
/// and omitted from the wire form until populated.
#[allow(
    clippy::derive_partial_eq_without_eq,
    reason = "area dicts hold serde_json::Value, which is not Eq (Number may be f64)"
)]
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct Task {
    /// Task level: `"lower"` (leaf) or `"upper"` (composite).
    pub level: TaskLevel,
    /// C++ source code for this task.
    pub code: String,
    /// Human-readable task name emitted by `tapacc` (e.g. the demangled
    /// template specialization). Required: `tapacc` emits it unconditionally
    /// for every task, equal to the task name for non-template tasks.
    pub readable_name: String,
    /// Per-task synthesis policy (`"hls"` / `"ignore"`).
    pub synth: SynthTarget,
    /// External ports / interface definitions.
    #[serde(default)]
    pub ports: Vec<Port>,
    /// Child task instantiations (upper tasks only).
    /// Maps task definition name → list of instantiations.
    #[serde(default)]
    pub tasks: BTreeMap<String, Vec<TaskInstance>>,
    /// FIFO / interconnect definitions (upper tasks only).
    #[serde(default)]
    pub fifos: BTreeMap<String, InterconnectDefinition>,
    /// Post-synthesis achieved clock-period estimate (seconds, stringified).
    /// Seeded empty by analyze, written by synth, read by report.
    #[serde(default, skip_serializing_if = "String::is_empty")]
    pub clock_period: String,
    /// Per-task self area dict (resource → number). Post-synthesis.
    #[serde(default, skip_serializing_if = "IndexMap::is_empty")]
    pub self_area: IndexMap<String, Value>,
    /// Per-task total area dict (self + descendants). Post-synthesis.
    #[serde(default, skip_serializing_if = "IndexMap::is_empty")]
    pub total_area: IndexMap<String, Value>,
}
---
//! Port and category types.

use regex_lite::Regex;
use serde::{Deserialize, Serialize};
use std::str::FromStr;
use std::sync::LazyLock;
use strum::{EnumString, IntoStaticStr};

static ARRAY_NAME_WITH_SUFFIX_RE: LazyLock<Regex> =
    LazyLock::new(|| Regex::new(r"^([a-zA-Z_]\w*)\[(\d+)\]([a-zA-Z_]\w*)?$").unwrap());

/// Collapse `name[idx]` into `name_{idx}`.
///
/// The frontend spells the channels of an array interface (`mmaps`,
/// `streams`) `name[i]`, and the brackets are load-bearing in the graph --
/// they let consumers recover which logical argument a channel belongs to.
/// Every projection to an RTL identifier collapses them, so this lives here,
/// on the schema, rather than in any one consumer: `tapa-codegen`,
/// `tapa pack` and `frt-cosim` must all agree on the name a port binds to.
#[must_use]
pub fn sanitize_array_name(name: &str) -> String {
    ARRAY_NAME_WITH_SUFFIX_RE.captures(name).map_or_else(
        || name.to_owned(),
        |caps| {
            format!(
                "{}_{}{}",
                &caps[1],
                &caps[2],
                caps.get(3).map_or("", |m| m.as_str())
            )
        },
    )
}

/// Convert a frontend name into a plain Verilog identifier.
///
/// Array channels keep their established `foo[3]` to `foo_3` spelling;
/// remaining characters that Verilog identifiers cannot contain become `_`.
#[must_use]
pub fn sanitize_identifier_name(name: &str) -> String {
    let name = sanitize_array_name(name);
    let mut out = String::with_capacity(name.len());
    for (index, character) in name.chars().enumerate() {
        let valid = character.is_ascii_alphanumeric() || matches!(character, '_' | '$');
        if index == 0 && character.is_ascii_digit() {
            out.push('_');
        }
        out.push(if valid { character } else { '_' });
    }
    out
}

/// Argument / port category.
///
/// `"hmap"` is an alias that deserializes to `Mmap`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, IntoStaticStr, EnumString)]
#[strum(serialize_all = "snake_case")]
pub enum ArgCategory {
    Istream,
    Ostream,
    Istreams,
    Ostreams,
    Scalar,
    #[strum(serialize = "mmap", serialize = "hmap")]
    Mmap,
    Immap,
    Ommap,
    #[strum(serialize = "async_mmap")]
    AsyncMmap,
}

impl Serialize for ArgCategory {
    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        serializer.serialize_str(self.as_str())
    }
}

impl<'de> Deserialize<'de> for ArgCategory {
    fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        let s = String::deserialize(deserializer)?;
        Self::from_str(&s).map_err(|_| serde::de::Error::custom(format!("unknown category: {s}")))
    }
}

impl ArgCategory {
    #[must_use]
    pub fn as_str(self) -> &'static str {
        if self == Self::Mmap {
            "mmap"
        } else {
            let s: &'static str = self.into();
            s
        }
    }

    /// Whether this is an input (consumer) stream port.
    #[must_use]
    pub const fn is_input_stream(self) -> bool {
        matches!(self, Self::Istream | Self::Istreams)
    }

    /// Whether this is an output (producer) stream port.
    #[must_use]
    pub const fn is_output_stream(self) -> bool {
        matches!(self, Self::Ostream | Self::Ostreams)
    }

    /// Whether this is any stream port (input or output).
    #[must_use]
    pub const fn is_stream(self) -> bool {
        self.is_input_stream() || self.is_output_stream()
    }

    /// Whether this is a scalar port.
    #[must_use]
    pub const fn is_scalar(self) -> bool {
        matches!(self, Self::Scalar)
    }

    /// Whether this is a memory-mapped port that binds directly to a
    /// top-level M-AXI interface (`mmap`/`async_mmap`), as opposed to
    /// `immap`/`ommap`, which connect two tasks inside the design.
    #[must_use]
    pub const fn is_direct_mmap(self) -> bool {
        matches!(self, Self::Mmap | Self::AsyncMmap)
    }

    /// Whether this is any memory-mapped port.
    #[must_use]
    pub const fn is_mmap_like(self) -> bool {
        matches!(
            self,
            Self::Mmap | Self::Immap | Self::Ommap | Self::AsyncMmap
        )
    }
}

/// An external port of a task.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct Port {
    /// Port category.
    pub cat: ArgCategory,
    /// Port name.
    pub name: String,
    /// C++ type (e.g. `"float"`, `"const float*"`, `"uint64_t"`).
    #[serde(rename = "type")]
    pub ctype: String,
    /// Bit width.
    pub width: u32,
    /// Channel count for hierarchical memory ports.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub chan_count: Option<u32>,
    /// Channel size for hierarchical memory ports.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub chan_size: Option<u32>,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn hmap_deserializes_to_mmap() {
        let json = r#""hmap""#;
        let cat: ArgCategory = serde_json::from_str(json).expect("parse hmap");
        assert_eq!(cat, ArgCategory::Mmap, "hmap must map to Mmap");
    }

    #[test]
    fn mmap_round_trips_as_mmap() {
        let cat = ArgCategory::Mmap;
        let json = serde_json::to_string(&cat).expect("serialize");
        assert_eq!(json, r#""mmap""#, "Mmap serializes as mmap");
    }

    #[test]
