425	fn direct_mmap_connection_expr(
426	    child_rtl: Option<&VerilogModule>,
427	    child_axi_port: &str,
428	    wire_name: &str,
429	    suffix: &str,
430	    m_axi_wire_id_width: Option<u32>,
431	    child_m_axi_id_width: Option<u32>,
432	) -> Expr {
433	    let is_id = matches!(suffix, "_ARID" | "_AWID" | "_BID" | "_RID");
434	    let Some(target_width) = m_axi_wire_id_width else {
435	        return Expr::ident(wire_name);
436	    };
437	    if !is_id || target_width <= 1 {
438	        return Expr::ident(wire_name);
439	    }
440	    let child_width = child_m_axi_id_width
441	        .or_else(|| {
442	            child_rtl
443	                .and_then(|module| module.find_port(child_axi_port))
444	                .and_then(tapa_rtl::port::Port::bit_width)
445	        })
446	        .unwrap_or(target_width);
447	    if child_width >= target_width {
448	        return Expr::ident(wire_name);
449	    }
450	    Expr::range(
451	        Expr::ident(wire_name),
452	        Expr::int(u64::from(child_width - 1)),
453	        Expr::int(0),
454	    )
455	}
