220	    child_task_name: &str,
221	    instance_name: &str,
222	    sig: &InstanceSignals,
223	    args: &BTreeMap<String, Arg>,
224	    mmap_bindings: &ChildMmapBindings,
225	    parent_fifos: &BTreeSet<String>,
226	    parent_rtl: Option<&VerilogModule>,
227	    child_rtl: Option<&VerilogModule>,
228	    reset_n: Expr,
229	) -> ModuleInstance {
230	    let mut port_args = Vec::new();
231	
232	    // Clock and reset
233	    port_args.push(PortArg::new(HANDSHAKE_CLK, Expr::ident(HANDSHAKE_CLK)));
234	    port_args.push(PortArg::new(HANDSHAKE_RST_N, reset_n));
235	
236	    // Handshake signals from InstanceSignals
237	    port_args.extend(sig.instance_portargs());
238	
239	    let resolve_child_stream_port = |name: &str, suffix: &str| {
240	        child_rtl
241	            .and_then(|module| module.get_port_of(name, suffix))
242	            .map_or_else(
243	                || format!("{}_s{}", sanitize_array_name(name), suffix),
244	                |p| p.name.clone(),
245	            )
246	    };
247	    let resolve_child_stream_peek_port =
248	        |name: &str, suffix: &str| resolve_peek_port_name(child_rtl?, name, suffix);
249	    // A stream argument binds to either a FIFO declared in the parent task
250	    // (signal wires are named `{fifo}{suffix}`, e.g. `a_q_dout`) or, for a
251	    // passthrough, the parent's own stream port. The parent port name is
252	    // resolved against the parent's RTL module: Vitis HLS spells it
253	    // `{port}_s{suffix}` for scalar streams but `{port}{suffix}` for array
254	    // elements (and `{base}_peek_{idx}{suffix}` for array peeks), so a fixed
255	    // `_s`/`_peek` infix does not fit all cases. The `{port}_s{suffix}` /
256	    // `{port}_peek{suffix}` fallbacks only apply when the parent module is
257	    // unavailable. The leaf module port itself is resolved separately by
258	    // `resolve_child_stream_port`.
259	    let stream_signal = |name: &str, suffix: &str| {
260	        let base = sanitize_array_name(name);
261	        if parent_fifos.contains(name) {
262	            return format!("{base}{suffix}");
263	        }
264	        parent_rtl
265	            .and_then(|module| module.get_port_of(name, suffix))
266	            .map_or_else(|| format!("{base}_s{suffix}"), |p| p.name.clone())
267	    };
268	    let peek_signal = |name: &str, suffix: &str| {
269	        let base = sanitize_array_name(name);
270	        if parent_fifos.contains(name) {
271	            return format!("{base}{suffix}");
272	        }
273	        parent_rtl
274	            .and_then(|module| resolve_peek_port_name(module, name, suffix))
275	            .unwrap_or_else(|| format!("{base}_peek{suffix}"))
276	    };
277	
278	    // Argument port bindings
279	    for (child_port, arg) in args {
280	        match arg.cat {
281	            ArgCategory::Scalar => {
282	                // Scalar: connect to per-instance pipeline signal
283	                let pipeline_name = format!("{instance_name}__{child_port}");
284	                port_args.push(PortArg::new(
285	                    child_port.as_str(),
286	                    Expr::ident(pipeline_name),
287	                ));
288	            }
289	            ArgCategory::Istream | ArgCategory::Istreams => {
290	                // Input stream: connect with ISTREAM_SUFFIXES
291	                for suffix in ISTREAM_SUFFIXES {
292	                    let signal = Expr::ident(stream_signal(&arg.arg, suffix));
293	                    port_args.push(PortArg::new(
